window.QUIZ_QUESTIONS=[[{"id": "Q1-01", "topic": "M4", "type": "multi", "stem": "A warehouse robot can move horizontally and vertically. In one operating mode it performs the two movements sequentially; in another it performs them simultaneously. For a destination requiring 6 and 8 seconds on the two axes, which statements correctly connect the distance measure to the task?", "options": ["Euclidean distance is always the right measure because the floor is two-dimensional", "Sequential travel takes 14 seconds and is represented by L1 on these time coordinates", "Simultaneous travel takes 8 seconds and is represented by L-infinity on these time coordinates", "Switching movement rules can change which station is nearest in operational travel time"]}, {"id": "Q1-02", "topic": "M3", "type": "multi", "stem": "Which activities belong to model selection and must avoid using the final test outcomes?", "options": ["Computing the locked model's final test score", "Choosing k for k-NN", "Choosing an SVM kernel", "Choosing a classification threshold"]}, {"id": "Q1-03", "topic": "M2", "type": "multi", "stem": "A quality team tunes a soft-margin SVM using the stated objective total classification-loss penalty + lambda times squared coefficient norm. It raises lambda, and training fit becomes worse. Which interpretations are justified?", "options": ["A larger lambda in this stated objective has to eliminate all training errors", "Validation is needed to judge whether the tradeoff improves generalization", "The deterioration in training fit alone proves the new setting is worse for deployment", "The change places more emphasis on the coefficient penalty"]}, {"id": "Q1-04", "topic": "M10", "type": "single", "stem": "A repair-time tree sends a new machine into a leaf containing training repair times 10, 14, and 18 hours. The manager claims the tree must predict exactly 14 hours and guarantee that the next repair will take 14 hours. What is the best correction?", "options": ["The tree must fit three separate slope coefficients in this leaf", "The leaf predicts the most frequent machine label instead of hours", "A tree cannot make numeric-response predictions", "An ordinary regression leaf predicts 14 hours, but the prediction is not a guarantee for an individual repair"]}, {"id": "Q1-05", "topic": "M4", "type": "multi", "stem": "A city needs different daytime and nighttime patrol locations. Which changes are analytically reasonable?", "options": ["Check patrol coverage and budgets for each period", "Keep the original pooled clustering solely because it has more records", "Cluster nighttime incidents separately", "Cluster daytime incidents separately"]}, {"id": "Q1-06", "topic": "M6", "type": "single", "stem": "An engineer wants an alarm for a sustained increase in axle temperature rather than a future price forecast. Which lecture method directly serves this purpose?", "options": ["Poisson regression", "CUSUM", "PCA", "k-means"]}, {"id": "Q1-07", "topic": "M10", "type": "multi", "stem": "A lender needs a probability that a borrower defaults and then a yes/no intervention rule. Historical default outcomes are coded 1 and 0; borrower attributes are available before lending. Which statements are appropriate?", "options": ["An SVM class score is automatically a probability between zero and one", "Logistic regression directly models a binary-event probability from attributes", "The intervention threshold should reflect the costs of missed defaults and unnecessary interventions", "A threshold can turn the estimated probability into a class or intervention decision"]}, {"id": "Q1-08", "topic": "M7", "type": "multi", "stem": "Which statements about single exponential smoothing are correct for 0<alpha<1?", "options": ["Recent observations receive larger weights than distant ones", "It explicitly models a seasonal cycle by itself", "Older observations remain represented in the previous level", "A larger alpha follows new observations more quickly"]}, {"id": "Q1-09", "topic": "M2", "type": "multi", "stem": "A plant compares a linear SVM with a classification tree. The SVM uses the rule x1>5, independent of x2. The tree also splits on x2 and reduces training errors from 12 to 11 by isolating one training observation. No held-out results are available. Which conclusions follow?", "options": ["The isolated observation raises an overfitting concern", "Using an extra predictor establishes that the tree will generalize better", "The tree is proven superior because it makes one fewer training error", "x2 does not affect predictions under the stated SVM rule"]}, {"id": "Q1-10", "topic": "M2", "type": "single", "stem": "A diagram has x1 on the horizontal axis and x2 on the vertical axis. A classifier predicts rejection to the right of the vertical line x1=4. A rejected observation moves upward without changing x1. Which interpretation is defensible?", "options": ["The rule proves that x2 is irrelevant to every possible classifier", "It remains rejected under this rule, although a different fitted model could still use x2", "The line is a threshold on x2 because it is vertical", "It becomes accepted because x2 increased"]}, {"id": "Q1-11", "topic": "M7", "type": "single", "stem": "A level-only exponential-smoothing forecast is 80 units. A single unusually high observation of 100 arrives; the update uses alpha=.25. Which set of conclusions is correct?", "options": ["The new level is 85; the update reacts partly to the new observation, and a single update does not prove a permanent shift", "The level becomes 85 and therefore all future actual observations must equal 85", "The new level is 20 because alpha multiplies the previous level only", "The new level is 100 because every new observation replaces the past"]}, {"id": "Q1-12", "topic": "M10", "type": "multi", "stem": "Two defect classifiers are evaluated on the same 1,000 representative cases. A has 3 missed defects and 10 false alarms; B has 1 missed defect and 30 false alarms. A miss costs $100, a false alarm costs $2, and correct decisions are free. Which statements are correct?", "options": ["A makes fewer total errors but has higher stated total error cost than B", "The preferred classifier can change if the stated error costs change", "A costs $320 on this evaluation set", "B costs $160 on this evaluation set"]}, {"id": "Q1-13", "topic": "M7", "type": "single", "stem": "A manufacturer records operating hours before failure once for each successive item. Batches contain exactly 120 items but take 5 to 7 calendar days. The question concerns patterns by position in each batch. Which setup fits the observation index?", "options": ["Use item position as the response because it defines the ordering", "Use operating hours before failure as x_t and 120 observations as the seasonal period", "Use 7 as the seasonal period because it is the longest calendar duration", "Use day within batch as x_t and 6 observations as the seasonal period"]}, {"id": "Q1-14", "topic": "M8", "type": "single", "stem": "A regression reports a positive temperature coefficient with a confidence interval entirely above zero. The data are observational, and temperature changes along with production speed. Which conclusion is strongest without additional causal evidence?", "options": ["The interval proves that the model includes every important predictor", "Production speed cannot matter because temperature is significant", "Temperature has a supported positive association under the fitted specification, but changing temperature alone is not proved to cause that response change", "Every temperature intervention must increase the response by exactly the coefficient"]}, {"id": "Q1-15", "topic": "M2", "type": "single", "stem": "A safety classifier deliberately accepts more training misclassifications to obtain a wider-margin solution. A colleague says an SVM must always prefer whichever classifier makes the fewest training errors. Which answer best reflects the lecture tradeoff?", "options": ["Any training misclassification makes the fitted SVM mathematically unusable", "SVM is designed to minimize training error with no regard to margin", "A wider margin guarantees zero deployment errors", "Soft-margin SVM balances fit and margin; the setting should be compared using validation and the relevant error consequences"]}, {"id": "Q1-16", "topic": "M1", "type": "multi", "stem": "An analyst says “we use regression,” then names predictors, then supplies fitted coefficients. Which statements about the word model are valid?", "options": ["It can mean a method family", "It always means only an algorithm", "It can mean a predictor specification", "It can mean a fitted equation"]}, {"id": "Q1-17", "topic": "M10", "type": "multi", "stem": "A screening model labels disease as positive. On 100 patients it yields TP=36, FN=4, FP=12, TN=48. A doctor asks both how often diseased patients are caught and how often a positive result is actually disease. Which statements answer those two questions?", "options": ["The fraction of diseased patients caught is 36/40", "The four missed diseased patients belong in the positive-prediction denominator", "Both questions use the same denominator because positive means diseased in every cell", "The fraction of positive predictions that are actual disease is 36/48"]}, {"id": "Q1-18", "topic": "M9", "type": "multi", "stem": "Which statements about ordinary PCA are correct?", "options": ["It uses predictors without response labels", "It produces orthogonal loading directions", "It ranks components by predictor variance", "Its first component must maximize classification accuracy"]}, {"id": "Q1-19", "topic": "M1", "type": "multi", "stem": "A hospital predicts tomorrow's arrivals, estimates waiting time under alternative staffing levels, and must choose a schedule subject to a staffing budget. Which statements correctly distinguish the steps?", "options": ["The final constrained staffing choice is prescriptive", "The objectives and staffing constraints matter beyond the arrival prediction", "Forecasting arrivals is a predictive input to the decision", "A model with the lowest forecasting error automatically selects the optimal feasible schedule"]}, {"id": "Q1-20", "topic": "M6", "type": "multi", "stem": "In upper CUSUM, which changes generally make the alarm less sensitive?", "options": ["Increase the threshold T", "Increase the allowance C", "Reduce both C and T", "Initialize every period's cumulative statistic to zero regardless of its value"]}, {"id": "Q1-21", "topic": "M9", "type": "multi", "stem": "A positive-valued cost response has a strongly skewed distribution and a regression shows increasing error spread at higher fitted values. A team proposes a Box-Cox transformation. Which statements are defensible at the lecture's level?", "options": ["The transformation guarantees a normal response and a correct regression specification", "Model diagnostics and validation still matter after the transformation", "The transformation can be considered to improve the suitability of the response for modeling", "Choosing the logarithmic member requires the response to be suitable for a log transformation"]}, {"id": "Q1-22", "topic": "M4", "type": "single", "stem": "Optimal WSS drops as k rises all the way to one cluster per distinct point. Why does selecting the smallest WSS alone fail?", "options": ["More clusters always cost less operationally", "WSS cannot be computed from centers", "It mechanically favors increasingly fine partitions", "WSS measures classification labels"]}, {"id": "Q1-23", "topic": "M8", "type": "single", "stem": "Two regression specifications are fit to the same response on the same observations. The more complex model has a better likelihood but a higher AIC. What is the best interpretation?", "options": ["Its gain in fit did not offset AIC's complexity penalty, so AIC favors the lower-score model", "AIC has established the causal effect of the added predictors", "Higher AIC is always preferred because it measures extra information learned", "Higher likelihood means the more complex model must have lower AIC"]}, {"id": "Q1-24", "topic": "M2", "type": "multi", "stem": "Income ranges in millions while a credit measure ranges in hundreds. Which preparations can make distances more comparable?", "options": ["Standardize each feature using training statistics", "Evaluate whether feature weights reflect the intended notion of similarity", "Multiply every income by 1,000 without justification", "Scale each feature using its training range"]}, {"id": "Q1-25", "topic": "M10", "type": "multi", "stem": "A large tree improves training accuracy by isolating one observation in a leaf. What conclusions are warranted?", "options": ["Validation or pruning can assess whether the split helps", "Using an extra feature necessarily makes the tree better", "That split is a warning sign for overfitting", "The training improvement alone does not prove better generalization"]}, {"id": "Q1-26", "topic": "M4", "type": "single", "stem": "A city is choosing emergency-response stations. Candidate A is closer to many incidents by straight-line distance but separated by a river; candidate B has a longer straight-line distance but a direct road route. Which conclusion best follows?", "options": ["Candidate A must be preferred because k-means always gives the operational optimum", "The coordinates cannot be used in any clustering analysis", "The distance used in the analysis should represent travel constraints; Euclidean closeness alone need not imply quicker response", "Candidate B must be preferred without measuring travel times"]}, {"id": "Q1-27", "topic": "M5", "type": "multi", "stem": "A single extreme production record is found. Which actions are justified before deciding whether to exclude it?", "options": ["Assess whether the intended model should cover that condition", "Delete it immediately because it reduces R-squared", "Investigate sensor or transcription problems", "Check whether an unusual real operating condition occurred"]}, {"id": "Q1-28", "topic": "M7", "type": "multi", "stem": "A financial team needs both tomorrow's expected return and how variable that return may be. Which statements distinguish the lecture methods?", "options": ["Mean and variance forecasts answer different planning questions", "GARCH addresses time-varying variance", "A GARCH variance forecast alone gives the signed expected return", "ARIMA can address a forecast of the series value"]}, {"id": "Q1-29", "topic": "M8", "type": "multi", "stem": "An additive wage regression gives an age coefficient of $500 per year while holding education and other included attributes fixed. Older employees in the data also tend to have more education. Which statements are supported?", "options": ["Adding an age-by-education interaction leaves the age effect independent of education", "The coefficient describes the fitted age association conditional on the included predictors", "It does not by itself prove that making an employee a year older causes a $500 wage increase", "It is necessarily the difference in average wages between every pair of employees one year apart"]}, {"id": "Q1-30", "topic": "M2", "type": "single", "stem": "A nearest-neighbor loan model treats ZIP code as a numeric coordinate. It concludes that ZIP codes 10001 and 10002 represent more similar borrowers than 10001 and 90210 solely because their numerical difference is smaller. What is the central modeling problem?", "options": ["Standardizing ZIP code necessarily makes the distance substantively meaningful", "A numeric-looking category identifier does not automatically define a meaningful distance", "Using ZIP code as a response instead will automatically solve the similarity problem", "Any five-digit value is quantitative by definition"]}, {"id": "Q1-31", "topic": "M8", "type": "multi", "stem": "Which regressions are linear in their fitted coefficients?", "options": ["log(y)=b0+b1*x", "y=b0+b1*x+b2*x squared", "y=b0+exp(b1*x)", "y=b0+b1*x1+b2*x1*x2"]}, {"id": "Q1-32", "topic": "M4", "type": "multi", "stem": "In one k-means iteration, a few remote customer locations are assigned to a cluster with a dense central group. Which statements describe the standard mean-center update and its interpretation?", "options": ["A centroid is necessarily a feasible service site because it is computed from real customer locations", "The remote locations can pull the center away from the dense group", "The updated center must equal one of the observed customer locations", "The new center is the mean of the currently assigned coordinates"]}, {"id": "Q1-33", "topic": "M3", "type": "single", "stem": "A retailer operating five days weekly assigns every second record to validation in a fixed five-record cycle. What is the central concern?", "options": ["Five-record cycles guarantee representative subsets", "The split may isolate a particular weekday", "Validation labels become quantitative", "The split necessarily duplicates records"]}, {"id": "Q1-34", "topic": "M10", "type": "single", "stem": "A team fits many trees that all tend to choose the same dominant predictor first and make similar mistakes. In the lecture's random-forest idea, why restrict which predictors a tree or split may consider?", "options": ["To eliminate the need for observed responses during training", "To prove that the excluded predictors have no relationship with the response", "To make every tree identical so averaging becomes exact", "To introduce diversity so the combined prediction can benefit from different strengths and weaknesses"]}, {"id": "Q1-35", "topic": "M5", "type": "single", "stem": "A temperature is normal in summer but extremely unusual for its recorded winter date. Which outlier type best describes it?", "options": ["Only a point outlier regardless of context", "Contextual", "A categorical response", "A principal component"]}, {"id": "Q1-36", "topic": "M7", "type": "multi", "stem": "Which interpretations of ARIMA(2,1,3) are correct?", "options": ["Two autoregressive lags are included", "Three lagged innovations are included", "The series is differenced once", "The method estimates three independent cluster centers"]}, {"id": "Q1-37", "topic": "M2", "type": "single", "stem": "A three-class k-NN rule sees five neighbors: red, red, blue, green, blue. What additional detail is needed to return a unique class?", "options": ["A tie-breaking rule", "The number of clusters", "An ARIMA differencing order", "A regression coefficient for every class"]}, {"id": "Q1-38", "topic": "M8", "type": "multi", "stem": "Which statements about a p-value of .01 for a coefficient are valid?", "options": ["It establishes that the effect is practically large", "It can indicate evidence against a zero-coefficient null", "It means a 1% probability that the coefficient equals zero", "It is computed assuming the tested null and statistical model"]}, {"id": "Q1-39", "topic": "M9", "type": "multi", "stem": "A team uses the first two principal components, which explain 90% of predictor variance, before fitting a classification model. Which statements are justified?", "options": ["The omitted low-variance direction might still contain useful class information", "The resulting predictive procedure should be validated rather than judged solely by explained predictor variance", "The retained components summarize 90% of the variation in the predictors under the fitted scaling", "The classifier must achieve 90% accuracy"]}, {"id": "Q1-40", "topic": "M4", "type": "multi", "stem": "Which statements describe standard Euclidean k-means correctly?", "options": ["It guarantees the globally best clustering from every start", "It uses no known response labels", "Multiple initializations can produce different final solutions", "It repeatedly assigns points and updates means"]}, {"id": "Q1-41", "topic": "M3", "type": "multi", "stem": "After CV chooses a model specification, which actions are appropriate?", "options": ["Evaluate the refitted model on reserved test data", "Refit the chosen specification on all non-test data", "Choose the fold with the luckiest validation score as the final model", "Average fold coefficients as the mandatory final model"]}, {"id": "Q1-42", "topic": "M6", "type": "single", "stem": "An upper CUSUM monitor has baseline 10, allowance 2, previous statistic 4, and new observation 15. Its rule alarms when the updated statistic is greater than 6. Which interpretation is correct?", "options": ["The observation alone proves that a new machine caused the shift", "An alarm means every later observation will exceed the baseline", "The statistic becomes 3 and confirms the process is stable", "The statistic becomes 7 and an alarm is triggered; the alarm supports investigation of an upward change but not a particular cause"]}, {"id": "Q1-43", "topic": "M7", "type": "single", "stem": "A multiplicative seasonal factor for early-batch parts is .8 and the response is operating hours before failure. What conclusion is supported?", "options": ["Early-batch parts last 80 extra hours", "There is no seasonal effect", "Workers' fatigue is proven to cause the pattern", "Early-batch parts have lower expected operating hours than the adjusted baseline"]}, {"id": "Q1-44", "topic": "M3", "type": "multi", "stem": "A team reserves 200 of 1,000 observations for a final test and uses four-fold validation on the other 800 to compare SVM settings. Which statements describe the fitting stages correctly?", "options": ["After selection, the chosen specification can be refit on all 800 non-test observations", "The final model should be whichever fold happened to score best", "The reserved 200 may be used to select lambda without affecting their independent-test role", "Each equal-sized fold fit uses 600 training observations and 200 validation observations"]}, {"id": "Q1-45", "topic": "M3", "type": "single", "stem": "Ten candidate models are fit on training data and the best validation performer is chosen. Which dataset should provide the final reported estimate?", "options": ["The same validation set after selecting the winner", "The training set", "An untouched test set", "The union of test and training data used to refit before scoring"]}, {"id": "Q1-46", "topic": "M2", "type": "blank", "stem": "After subtracting a feature's mean and dividing by its standard deviation, the transformed feature has mean ____ and standard deviation ____.", "options": []}, {"id": "Q1-47", "topic": "M3", "type": "tf", "stem": "A test set remains an independent final evaluation set even if its labels were used to choose the best threshold.", "options": []}, {"id": "Q1-48", "topic": "M4", "type": "blank", "stem": "A k-means grouping was learned without response labels. Assigning a new observation to its closest learned center does not change the original fit into ____ learning.", "options": []}, {"id": "Q1-49", "topic": "M7", "type": "tf", "stem": "For ordinary Holt forecasting, the h-step-ahead forecast is current level plus h times current trend.", "options": []}, {"id": "Q1-50", "topic": "M10", "type": "blank", "stem": "For TP=36 and FP=12, precision is ____.", "options": []}], [{"id": "Q2-01", "topic": "M2", "type": "multi", "stem": "Which reasons can justify kernel SVM rather than a strictly linear separator?", "options": ["The feature-label relationship has a curved boundary", "Kernel SVM proves causal mechanisms", "A nonlinear separator may fit patterns missed by a straight hyperplane", "Suitable kernel settings improve validation performance"]}, {"id": "Q2-02", "topic": "M4", "type": "multi", "stem": "A customer-segmentation run reports WSS=26 for k=1 and WSS=0 when every observed customer has a separate center. A manager selects the second run solely because zero looks perfect. Which criticisms are justified?", "options": ["Zero WSS proves that all future customers will be assigned correctly to meaningful groups", "An operationally useful k may be smaller even with positive WSS", "WSS rewards extra clusters and does not by itself establish a useful segmentation", "An elbow and the intended use can help assess whether added clusters are worthwhile"]}, {"id": "Q2-03", "topic": "M7", "type": "multi", "stem": "Daily orders show both an increasing baseline and a repeatable seven-day pattern. A Holt-Winters update is processing Tuesday. Which statements correctly distinguish its components?", "options": ["Trend and seasonality describe the same component and need only one state", "The seasonal comparison uses the previous estimate for the same weekday", "A Tuesday seasonal factor above one indicates a response above the current baseline in the multiplicative formulation", "Changing the response units from dollars to cents changes the number of days in the seasonal cycle"]}, {"id": "Q2-04", "topic": "M10", "type": "multi", "stem": "A random forest and a single classification tree are trained on labeled claims. The forest lets different trees consider different predictor sets and combines their class predictions. Which claims are defensible at the lecture's level?", "options": ["Combining diverse trees can improve predictive performance but still requires validation", "Every forest must be easier to explain as a single sequence of rules than an individual tree", "The forest no longer needs known claim labels because the trees are randomized", "The randomized predictor sets can produce trees with different strengths"]}, {"id": "Q2-05", "topic": "M7", "type": "multi", "stem": "Which statements distinguish additive from multiplicative seasonality?", "options": ["Multiplicative seasonality represents a proportion of level", "A factor of 1 indicates no multiplicative seasonal change", "A factor of zero is always safe in division-based Holt-Winters updates", "Additive seasonality represents a unit offset"]}, {"id": "Q2-06", "topic": "M7", "type": "single", "stem": "A sales team has an ordered response series with a changing mean. After one differencing step, it wants to use two previous modeled values and one previous prediction error. Which ARIMA description matches that specification?", "options": ["ARIMA(2,1,1): two autoregressive lags, one differencing step, one error lag", "ARIMA(1,2,1): one value lag and two error lags", "ARIMA(2,0,1): two lags means differencing occurs automatically", "GARCH(2,1): its variance is the same response as sales"]}, {"id": "Q2-07", "topic": "M3", "type": "single", "stem": "A flexible spline has training MSE zero and much higher held-out MSE than a straight-line model. What is the best interpretation?", "options": ["The line cannot represent any real effect", "The held-out observations should be added to training before comparison", "The spline may fit dataset-specific noise", "The spline must be preferred because its training fit is exact"]}, {"id": "Q2-08", "topic": "M7", "type": "multi", "stem": "A factory uses single exponential smoothing. During a persistent upward shift, a setting with very small alpha changes its forecast only slowly. Which conclusions follow?", "options": ["A larger alpha would put more weight on the latest observation", "Small alpha gives more persistence to the previous level", "Increasing alpha guarantees fewer false alarms and better future predictions", "Changing alpha alone adds an explicit trend and seasonal component"]}, {"id": "Q2-09", "topic": "M10", "type": "single", "stem": "For one repair request, three regression trees predict 8, 10, and 15 hours. The combined forest averages their outputs. Which conclusion is correct?", "options": ["It predicts 15 hours because a forest always selects the largest tree output", "It cannot combine trees that produce different predictions", "It predicts 11 hours; averaging does not prove the actual repair time or a causal explanation", "It predicts the most common class label rather than a numeric time"]}, {"id": "Q2-10", "topic": "M8", "type": "multi", "stem": "A retailer believes marketing emails affect spending differently for younger and older customers. Its current additive regression imposes one common email coefficient. Which lecture-level revisions could represent that variation?", "options": ["Use a tree to define groups with different fitted responses or local relationships", "Increase the common email coefficient and claim that it now differs by age", "Add an email-by-age interaction to the regression", "Choose the revision with the best training fit without evaluating new cases"]}, {"id": "Q2-11", "topic": "M1", "type": "single", "stem": "A restaurant first predicts next week's demand, then chooses purchase quantities under spoilage and shortage costs. What is the role of the demand forecast?", "options": ["An unsupervised class label", "A proof of customer causation", "The final purchasing decision by itself", "A predictive input to a prescriptive decision"]}, {"id": "Q2-12", "topic": "M7", "type": "single", "stem": "A Holt forecast has level 100 and trend -3 response units per observation. The team wants a four-observation-ahead point forecast. Which interpretation is correct?", "options": ["The negative trend proves that a recently introduced policy caused the decline", "The forecast is 88, extending the estimated trend, not guaranteeing four future observations will fall by exactly three", "The forecast is 97 because the horizon never matters", "The forecast is 112 because trend magnitude is always added"]}, {"id": "Q2-13", "topic": "M4", "type": "single", "stem": "A new point is equally far from two learned centers. What is needed for deterministic cluster assignment?", "options": ["A different number of CV folds", "A tie policy", "A logistic response", "A new supervised label for every training point"]}, {"id": "Q2-14", "topic": "M7", "type": "multi", "stem": "Demand forecasts from a mean model are reasonably centered, but forecast errors have periods of small variability and periods of large variability. Management wants to size a reserve against uncertainty. Which statements are appropriate?", "options": ["A larger variance estimate implies greater modeled variability, not necessarily a higher demand mean", "The mean forecast can remain useful even when a separate variance model is needed", "A GARCH model can address changing variance", "A variance model alone determines whether the next error will be positive or negative"]}, {"id": "Q2-15", "topic": "M2", "type": "single", "stem": "A seven-neighbor classifier finds labels A,A,A,B,B,C,C. An analyst rejects the result because no class has a majority. Which response best matches unweighted multiclass k-NN?", "options": ["Class A wins by plurality; the highest vote count need not exceed half of k", "The classifier must return the numerical mean of the letters", "There is necessarily a three-way tie because no class exceeds 50%", "The method can classify only two classes"]}, {"id": "Q2-16", "topic": "M4", "type": "multi", "stem": "Which statements about k-means cluster centers are correct?", "options": ["They are known response labels supplied before fitting", "They need not be observed data points", "An extreme point can pull a center", "They are coordinatewise means under the standard objective"]}, {"id": "Q2-17", "topic": "M4", "type": "single", "stem": "A rescue robot must finish moving on both axes before it can act. The required horizontal and vertical travel times are 5 and 12 seconds, and the motions occur simultaneously. A teammate uses Euclidean distance because it gives 13. What is the best correction?", "options": ["Any norm is equally appropriate because the destination is unchanged", "Euclidean length is always the completion time for two-axis movement", "The completion time is 12 seconds under simultaneous independent motions; the maximum, not the Euclidean length, matches this task", "The completion time is 17 seconds because concurrent movements must be added"]}, {"id": "Q2-18", "topic": "M2", "type": "multi", "stem": "A loan team has amount, payment method, repayment outcome, and a late-fee total recorded after the repayment deadline. It wants to predict repayment before approving a new loan. Which statements are correct?", "options": ["Post-deadline late fees should not be treated as information available at approval", "Changing the algorithm from logistic regression to SVM fixes unavailable-predictor leakage", "Repayment outcome supplies historical labels for supervised learning", "Random splitting makes post-deadline information legitimate for an approval-time prediction"]}, {"id": "Q2-19", "topic": "M4", "type": "multi", "stem": "When comparing repeated k-means starts at the same k, which practices make sense?", "options": ["Ensure the distance and scaling are consistent across runs", "Recognize that different starts can converge to the same solution", "Choose the center ordering with the prettiest labels", "Keep the solution with lower WSS on the same prepared data"]}, {"id": "Q2-20", "topic": "M8", "type": "multi", "stem": "A regression is fitted by minimizing squared prediction errors. Its modeling argument assumes independent, identically distributed normal errors. Which statements connect this to the lecture's likelihood discussion?", "options": ["The best likelihood automatically eliminates overfitting from added predictors", "The error assumptions are part of why that equivalence holds", "Under those assumptions, coefficient estimates minimizing squared errors also maximize the corresponding likelihood", "The result proves that every regression dataset has normal errors"]}, {"id": "Q2-21", "topic": "M3", "type": "multi", "stem": "Which statements distinguish underfitting from overfitting?", "options": ["Both are assessed solely by choosing the largest training R-squared", "Validation can help choose an appropriate flexibility level", "An overly flexible form may fit random structure", "An overly restrictive form may miss real structure"]}, {"id": "Q2-22", "topic": "M6", "type": "single", "stem": "A CUSUM analysis of temperatures signals that a warm period lasted longer in one region. A report attributes the signal to one newly implemented policy. Which evaluation is most defensible?", "options": ["CUSUM labels the cause of each mean shift as part of its output", "The result should be accepted only if its conclusion matches the analyst's prior belief", "Changing the definition until the preferred conclusion appears strengthens the evidence", "The signal depends on the baseline, settings, and data definition; it does not by itself identify the policy as the cause"]}, {"id": "Q2-23", "topic": "M2", "type": "multi", "stem": "A feature's training minimum and maximum are 20 and 60. A new case has value 70. The team applies the same min-max transformation used in training. Which conclusions follow?", "options": ["The scaler must be recomputed using the test cases to force them into the training interval", "An out-of-range transformed value alone proves the raw observation is an error", "A value above one can occur because the new case lies outside the fitted training range", "The new transformed value is 1.25"]}, {"id": "Q2-24", "topic": "M2", "type": "single", "stem": "Two soft-margin SVM settings are tested on the same held-out defect cases. Setting A has more training errors but fewer held-out missed defects and lower stated total decision cost than B. Which recommendation best follows?", "options": ["Favor A for the stated objective, subject to an independent final evaluation after selection", "Favor B because a wider margin always costs more in deployment", "Reject A because any training error makes SVM unusable", "Favor B because fewer training errors overrides the deployment objective"]}, {"id": "Q2-25", "topic": "M2", "type": "single", "stem": "Two analysts use the symbol lambda for different SVM tradeoffs. In one stated objective lambda multiplies the margin-related coefficient penalty; in the other it multiplies the fitting-loss penalty. Which conclusion is defensible?", "options": ["One cannot infer the same tuning direction from the symbol alone; inspect the term it multiplies", "Larger lambda always means fewer training errors regardless of the objective", "The symbol determines whether the model uses labeled or unlabeled data", "The two lambda values must be numerically equal for the models to be comparable"]}, {"id": "Q2-26", "topic": "M2", "type": "single", "stem": "A hard-margin SVM illustration shows two parallel margin boundaries with the closest class points touching them. Another separator also classifies all training points correctly but has a narrower margin. What feature makes the maximum-margin solution preferred under this model's objective?", "options": ["It guarantees that every future observation will be classified correctly", "It predicts a separate probability for every support vector", "Its wider separation from the nearest class points, rather than merely the count of correctly classified training cases", "It must use more predictors than the other separator"]}, {"id": "Q2-27", "topic": "M6", "type": "multi", "stem": "What information is needed to tune change-detection settings sensibly?", "options": ["The assumption that false alarms are always harmless", "Costs of false alarms", "Representative behavior before and after changes", "Costs of detection delay"]}, {"id": "Q2-28", "topic": "M9", "type": "multi", "stem": "Which steps correctly detrend a response for factor-based modeling?", "options": ["Add back the relevant trend when recovering original-scale predictions", "Estimate an appropriate time trend on the permitted training data", "Subtract that fitted trend from observed responses", "Assume detrending always eliminates every seasonal pattern"]}, {"id": "Q2-29", "topic": "M8", "type": "multi", "stem": "Which statements about increasing regression complexity are correct for nested least-squares fits with an intercept on the same training data?", "options": ["Adjusted R-squared may decrease", "Test error is guaranteed to decrease", "Training R-squared cannot decrease", "Training SSE cannot increase"]}, {"id": "Q2-30", "topic": "M2", "type": "multi", "stem": "A feature is standardized to z=(x-50)/10. Which statements are correct?", "options": ["A skewed distribution necessarily becomes normal", "x=70 maps to z=2", "Every resulting z must be between zero and one", "x=30 maps to z=-2"]}, {"id": "Q2-31", "topic": "M10", "type": "multi", "stem": "A repair tree first asks whether machine age is below 30 months. For the older branch it then asks whether load is below 50 units. A new machine is 40 months old with load 60. The reached leaf has only two training cases. Which statements are justified?", "options": ["Use the response estimate associated with the reached leaf", "Follow the older-machine branch and then the load-at-least-50 branch", "The very small leaf warrants concern about the stability of its prediction", "Average predictions from all leaves because every tree is a forest"]}, {"id": "Q2-32", "topic": "M9", "type": "single", "stem": "Two centered and standardized predictors measure production position and elapsed production day. They are highly positively correlated. PCA produces a dominant first component. Which interpretation is defensible?", "options": ["The component with the larger eigenvalue must explain the same percentage of response variation", "Highly correlated predictors force the two component variances to be equal", "PCA has established which variable causes failures", "Most predictor variation lies along a shared direction; this does not prove that component is the best predictor of failure time"]}, {"id": "Q2-33", "topic": "M10", "type": "multi", "stem": "A logistic model predicts 0.70 probability of repayment for one applicant, and the lending rule grants a loan at 0.80 or above. Which statements distinguish the outputs?", "options": ["The model must output 0.70 dollars as the predicted loan amount", "A different decision threshold can change the action without changing the fitted probability for this applicant", "Under the stated rule the applicant is classified below the loan-granting threshold", "The probability estimate is 0.70"]}, {"id": "Q2-34", "topic": "M7", "type": "single", "stem": "A time series has a drifting mean, while differences between consecutive observations fluctuate around a much more stable mean. Which ARIMA choice addresses the described feature most directly?", "options": ["Increasing the number of error lags guarantees that the mean becomes stationary", "A differencing step, with its adequacy checked on the resulting series", "PCA always removes temporal drift even when fitted without time information", "Replacing the response values with a variance forecast necessarily removes the drift"]}, {"id": "Q2-35", "topic": "M3", "type": "single", "stem": "A forecasting model will use data through Friday to predict Saturday. Which evaluation design best mirrors deployment?", "options": ["Use the same observations for fitting and testing", "Train on earlier periods and validate on later periods", "Predict Friday using Saturday's realized response", "Randomly intermingle future and past records for every fit"]}, {"id": "Q2-36", "topic": "M5", "type": "multi", "stem": "Which statements about large residuals are correct?", "options": ["They can indicate a missing predictor or wrong model form", "They prove the corresponding observation is invalid", "They merit investigation in the intended application", "They can indicate data errors"]}, {"id": "Q2-37", "topic": "M3", "type": "multi", "stem": "Which preprocessing practices avoid leakage in cross-validation?", "options": ["Fit PCA to all observations before making folds", "Estimate feature means on each fold's training portion", "Apply those fitted means to the held-out fold", "Select predictors using only the fold's training outcomes"]}, {"id": "Q2-38", "topic": "M9", "type": "multi", "stem": "Which conclusions follow from retaining all orthonormal PCA components of a feature space?", "options": ["The number of predictors automatically becomes one", "The representation changes coordinates", "No information is discarded solely by the full rotation", "Every component becomes causally interpretable"]}, {"id": "Q2-39", "topic": "M8", "type": "multi", "stem": "Two regressions predict a numeric response on the same held-out observations. A has lower held-out squared error but uses a sensor that becomes available only after the decision; B has slightly higher error using timely attributes. Which conclusions follow?", "options": ["A must be chosen because squared error is the only relevant modeling consideration", "Prediction-time feasibility can favor B despite its higher measured error", "A's reported error does not establish that it can serve the stated decision time", "Replacing A with a tree automatically makes the late sensor timely"]}, {"id": "Q2-40", "topic": "M7", "type": "multi", "stem": "Which statements about ARIMA's moving-average component are correct?", "options": ["Its order q counts innovation lags", "It can coexist with an autoregressive component", "It uses past innovations", "It necessarily averages the last q raw observations equally"]}, {"id": "Q2-41", "topic": "M3", "type": "single", "stem": "Two model families are compared using five equally sized validation folds. A averages error 6 but varies markedly between folds; B averages 6.2 with more stable results. Which claim is most appropriate?", "options": ["A's average proves it will outperform B in every deployment population", "B should be preferred solely because its error is higher", "The winning fold from A is necessarily the final fitted model", "A has the lower reported average, but the small difference and variation warrant caution and a separate final evaluation"]}, {"id": "Q2-42", "topic": "M6", "type": "single", "stem": "For upper CUSUM, previous S=3, x=7, mu=10, C=1. What is the new statistic?", "options": ["21", "4", "0", "-1"]}, {"id": "Q2-43", "topic": "M1", "type": "multi", "stem": "Which statements about inference and prediction are reasonable?", "options": ["Predictive success alone establishes the mechanism of a relationship", "Maximum flexibility always minimizes future error", "A less interpretable method may be useful when predictive accuracy is the priority", "An interpretable model can help explain modeled associations"]}, {"id": "Q2-44", "topic": "M5", "type": "single", "stem": "A heartbeat sequence lacks one expected beat, but none of the observed amplitudes is unusual. Which representation can expose a point outlier?", "options": ["Time between consecutive beats", "Only the sensor's ZIP code", "Unordered amplitudes alone", "A constant indicator for every observation"]}, {"id": "Q2-45", "topic": "M8", "type": "multi", "stem": "A regression has R-squared=.60 on its training data. Adding predictors raises it to .70, but held-out prediction error increases. Which statements are justified?", "options": ["The higher R-squared proves better held-out predictions", "The additional predictors may be fitting patterns that do not generalize", "The training fit improved by this measure", "Held-out error and complexity considerations matter when selecting the specification"]}, {"id": "Q2-46", "topic": "M4", "type": "blank", "stem": "For coordinate differences of 6 and 8, Manhattan distance is ____.", "options": []}, {"id": "Q2-47", "topic": "M5", "type": "tf", "stem": "If removing an outlier improves fit, that alone proves removal is appropriate for the intended application.", "options": []}, {"id": "Q2-48", "topic": "M7", "type": "blank", "stem": "With level=200, trend=5, and the next multiplicative seasonal factor=1.2, the one-step forecast is ____.", "options": []}, {"id": "Q2-49", "topic": "M8", "type": "tf", "stem": "A low p-value is sufficient evidence that changing the predictor will cause the estimated change in the response.", "options": []}, {"id": "Q2-50", "topic": "M10", "type": "blank", "stem": "If a classification leaf has 9 positive and 3 negative training cases, its empirical positive fraction is ____.", "options": []}], [{"id": "Q3-01", "topic": "M3", "type": "multi", "stem": "Which split designs can address nonrepresentative subsets?", "options": ["Stratify by important classes when appropriate", "Check whether systematic rotation aligns with periodic structure", "Consider relevant regimes or groups", "Assume random splits always preserve every rare condition"]}, {"id": "Q3-02", "topic": "M8", "type": "multi", "stem": "A regression coefficient is estimated at -4, with a reported 95% confidence interval from -9 to 1. The manager says this proves there is no association and proposes deleting the predictor without checking prediction quality. Which statements are warranted?", "options": ["The interval proves the coefficient is exactly zero", "The estimate is negative, but the reported uncertainty includes positive and negative values", "Predictive usefulness should be evaluated rather than inferred solely from whether the interval includes zero", "The interval includes zero, so it does not give strong evidence against a zero coefficient at the matching conventional level"]}, {"id": "Q3-03", "topic": "M7", "type": "single", "stem": "A sensor team has an ordered numeric series and two requests: forecast the next reading and alarm on a sustained increase from an established baseline. Which pair most directly assigns the lecture methods to those tasks?", "options": ["ARIMA or smoothing for the reading forecast, and CUSUM for accumulated evidence of an upward change", "CUSUM for the exact future reading, and PCA for the change alarm", "GARCH alone for both the expected reading and its exact change date", "K-means for the next reading and logistic regression without labels for the shift"]}, {"id": "Q3-04", "topic": "M9", "type": "single", "stem": "Two orthogonal PCA loadings produce a high-variance component unrelated to outcome and a low-variance component that separates classes. What does PCA alone recommend retaining first?", "options": ["Both components must receive equal ranks", "The outcome-separating component by definition", "No component because classes exist", "The high-variance component"]}, {"id": "Q3-05", "topic": "M2", "type": "multi", "stem": "A scaled linear SVM assigns zero coefficient to x2, while a tree using the same labeled data splits on x2 in one region. Which conclusions are justified?", "options": ["x2 can matter in a different representation or regional rule", "x2 does not affect this particular fitted linear SVM score", "The tree's use of x2 proves its predictions are better", "The zero coefficient proves x2 has no real-world association or causal effect under any circumstances"]}, {"id": "Q3-06", "topic": "M7", "type": "multi", "stem": "Two level-only smoothing models forecast weekly sales. One uses alpha=.8, the other .2. Last week had a one-off promotion unlikely to recur. Which statements correctly describe the tradeoff?", "options": ["The promotion's relevance to the forecast target should be investigated rather than judging settings solely by that week's fit", "The .8 update puts more weight on the promotion observation", "The .2 update retains more of the previous level", "The larger alpha is guaranteed to forecast ordinary future weeks better"]}, {"id": "Q3-07", "topic": "M4", "type": "multi", "stem": "Which changes alter the substantive clustering problem?", "options": ["Change the distance metric", "Switch from miles to dollars on one dimension without scaling policy", "Rename clusters from 1,2 to blue,red while keeping membership unchanged", "Analyze day and night separately when their distributions differ"]}, {"id": "Q3-08", "topic": "M7", "type": "single", "stem": "A multiplicative Holt-Winters implementation begins with seasonal factors of one and initial trend zero. The analyst reports that the underlying process has no seasonality or trend because those are the starting values. What is the best correction?", "options": ["An initial zero trend prevents later trend updates", "A factor of one proves every seasonal phase is identical for all future periods", "Seasonal factors of one mean all response observations equal one", "Initialization is a starting estimate; later observations update the states and can reveal trend or seasonal differences"]}, {"id": "Q3-09", "topic": "M6", "type": "single", "stem": "A clinic monitors reductions in service time with lower CUSUM S_new=max(0,S_previous+mu-x-C). Baseline is 20, allowance 1, previous statistic 2, and new time 16. The alarm threshold is 6, triggered only when S_new>6. Which conclusion is correct?", "options": ["The statistic is 5 and the alarm proves a staffing change caused the improvement", "The statistic is 7 because the allowance should be added", "The statistic is zero because only upward changes can be detected", "The statistic is 5; the low observation adds downward-change evidence but does not yet trigger this rule"]}, {"id": "Q3-10", "topic": "M2", "type": "single", "stem": "A k-NN model has good training behavior but poor validation performance after adding many irrelevant dimensions. What is a sensible next step?", "options": ["Choose k by the final test error repeatedly", "Convert all labels to missing values", "Keep every dimension because more features always help", "Evaluate feature selection or meaningful weighting inside validation"]}, {"id": "Q3-11", "topic": "M10", "type": "multi", "stem": "A classification tree splits a leaf into two small leaves and obtains perfect training labels in both. Held-out classification becomes worse. Which statements correctly interpret the result?", "options": ["The split improved training fit", "Pruning or increasing the support required for a split can be sensible responses", "The new leaves may be too specialized to their training cases", "Perfect training labels prove the split captured a stable population rule"]}, {"id": "Q3-12", "topic": "M10", "type": "single", "stem": "A retailer compares an interpretable single tree with a random forest. The forest performs better on validation, but the retailer must explain each declined application through a short sequence of rules. Which conclusion follows?", "options": ["The forest automatically supplies one unique branch path explaining the whole ensemble", "The tree must be best because interpretable models always predict better", "Predictive performance and explanation requirements both matter; the forest's validation gain does not by itself resolve the choice", "The objective can ignore explanation constraints whenever many trees are available"]}, {"id": "Q3-13", "topic": "M3", "type": "multi", "stem": "A team compares several SVM penalties and several k-NN neighborhood sizes using cross-validation. One SVM specification has the best mean validation result. Which actions are appropriate?", "options": ["Refit that selected specification using all non-test observations", "Use an untouched final test set to assess the selected procedure", "Treat the mean validation result as an independent final test after using it to choose the winner", "Retain only the coefficients from the best-scoring fold because they must be the final optimum"]}, {"id": "Q3-14", "topic": "M8", "type": "single", "stem": "On the same dataset, model A has slightly worse likelihood but fewer parameters than B. A has lower AIC; B has lower unpenalized fitting error. Which conclusion is supported?", "options": ["Different criteria cannot disagree when the data are the same", "AIC must always select the model with the lowest training error", "The criteria emphasize different tradeoffs, so B's better fit does not refute AIC's preference for A", "A's lower AIC proves every coefficient is causal"]}, {"id": "Q3-15", "topic": "M4", "type": "multi", "stem": "A k-means plan has WSS values 400, 210, 110, 98, and 90 for k=1 through 5. Managers can staff at most three service centers. Which interpretations make sense?", "options": ["The curve suggests a candidate elbow near three clusters", "The smallest listed WSS means five centers must be selected despite the staffing constraint", "The elbow is evidence to assess alongside service coverage, not proof that three is universally optimal", "The operational limit supports considering three or fewer centers"]}, {"id": "Q3-16", "topic": "M9", "type": "multi", "stem": "PCA produces two components from centered, standardized production measurements. A loading combines several measurements, rather than identifying one original column to keep. Which distinctions are correct?", "options": ["A large component loading establishes an original feature's causal importance", "Keeping only the first component is identical to selecting whichever original feature has the largest mean", "PCA is feature extraction because it creates combinations of the original features", "The loadings describe directions used to compute component scores"]}, {"id": "Q3-17", "topic": "M2", "type": "multi", "stem": "A rare toxic class is costly to miss. Which classification adjustments can be appropriate?", "options": ["Evaluate the resulting false alarms and total cost", "Use a lower toxic-probability threshold if miss costs dominate", "Force a threshold of .5 because probabilities require symmetry", "Increase the penalty for missing toxic cases"]}, {"id": "Q3-18", "topic": "M8", "type": "multi", "stem": "A regression estimates a $0.001 spending difference per exposure unit with a very small p-value. The action needed to change exposure costs much more than the expected spending difference. Which statements are justified?", "options": ["The coefficient's units and practical size matter", "The cost comparison belongs to the decision question in addition to the modeling question", "A small p-value guarantees the intervention is worthwhile and causal", "Statistical evidence for an association does not ensure economically valuable action"]}, {"id": "Q3-19", "topic": "M5", "type": "multi", "stem": "A clustering analysis identifies a small but verified customer group far from most observations. Removing the group improves WSS and a regression's fit. The business wants to serve all customer types. Which statements are defensible?", "options": ["Better fit alone is not a sufficient reason to delete legitimate target customers", "The group may reflect a meaningful segment rather than bad data", "Separate analysis or reporting may help preserve the group's operational importance", "All small clusters are measurement errors by definition"]}, {"id": "Q3-20", "topic": "M10", "type": "multi", "stem": "A regression-tree split reduces within-node response variation, but one proposed child has very few observations. Which steps reflect the lecture's branching and pruning ideas?", "options": ["Keep every split with any training improvement regardless of leaf support", "Use a quality-related splitting criterion together with safeguards against overfitting", "Check whether the split improves estimation on separate data during pruning", "Require enough data in each resulting leaf rather than splitting solely for a training improvement"]}, {"id": "Q3-21", "topic": "M10", "type": "single", "stem": "An airport needs expected arrival counts from time of day and holiday status. A second project has few labeled cases but useful expert beliefs about regression coefficients. Which pairing matches the survey introductions?", "options": ["Poisson regression requires the same arrival rate at every time and holiday status", "PCA for arrival probabilities and CUSUM for prior coefficient beliefs", "Poisson regression for the count-rate task; Bayesian regression to combine the second project's prior information with data", "Bayesian regression guarantees that experts override all observed evidence"]}, {"id": "Q3-22", "topic": "M2", "type": "multi", "stem": "A classifier uses a horizontal boundary x2=5. Points above it are positive. A tree built from the same data uses both x1 and x2 and makes fewer training errors. Which statements are supported?", "options": ["A horizontal boundary means that x1 must control the class", "The tree may use a predictor that this particular linear rule does not use", "Fewer training errors establish the tree's deployment superiority", "x1 does not change the class under the stated horizontal rule"]}, {"id": "Q3-23", "topic": "M2", "type": "single", "stem": "A sensor feature is constant in all training observations. The team wants to standardize every feature and use k-NN. Which handling is defensible?", "options": ["The constant feature guarantees better neighbor discrimination", "An undefined standardized coordinate should be silently treated as an extremely large distance", "The standardized feature must become a normal distribution", "Recognize the zero standard deviation and handle the feature explicitly rather than dividing by zero"]}, {"id": "Q3-24", "topic": "M1", "type": "multi", "stem": "A delivery company groups unlabeled route profiles, predicts delay probability from labeled deliveries, and chooses extra driver staffing under a budget. Which statements correctly describe the pipeline?", "options": ["Grouping profiles can be an unsupervised descriptive step", "Estimating delay probability is a supervised predictive step", "The budget-constrained staffing choice is a prescriptive step", "Every step is the same task because each uses delivery data"]}, {"id": "Q3-25", "topic": "M7", "type": "multi", "stem": "Which quantities enter the lecture's multiplicative Holt-Winters level update?", "options": ["A level smoothing coefficient alpha", "Previous level plus previous trend", "Current observation divided by the previous same-phase seasonal factor", "Tomorrow's actual observed response"]}, {"id": "Q3-26", "topic": "M2", "type": "single", "stem": "A linear classifier predicts positive when 2*x1-3*x2+6>0. An observation starts at (0,1); only x2 increases to 3. Which interpretation is correct?", "options": ["Increasing either predictor must always move toward the same class", "The prediction stays positive because x1 did not change", "The prediction changes from positive to negative; the score is a decision quantity rather than automatically a probability", "The score at the starting point is a valid probability of three"]}, {"id": "Q3-27", "topic": "M10", "type": "multi", "stem": "A clinician estimates infection probability at .08. An unnecessary follow-up costs $10; missing an infection costs $200; correct decisions are free. Compare follow-up to no follow-up under these stated costs. Which statements are correct?", "options": ["Expected no-follow-up error cost is .08*$200=$16", "Expected follow-up error cost is .92*$10=$9.20", "Follow-up has lower stated expected error cost, although this simplified calculation does not include unstated consequences", "No follow-up must be preferred whenever probability is below .50"]}, {"id": "Q3-28", "topic": "M7", "type": "multi", "stem": "A process records one response per completed part. Each 80-part batch lasts a variable number of days, and early parts repeatedly have lower operating hours before failure. Which modeling interpretations are justified?", "options": ["An item-indexed seasonal analysis can use a period of 80", "A positive trend in this response would indicate increasing operating hours before failure across the index", "The seasonal pattern itself proves workers are careless at the start of each batch", "A multiplicative early-batch factor below one corresponds to lower hours before failure"]}, {"id": "Q3-29", "topic": "M4", "type": "multi", "stem": "A new customer is assigned to the closest of several stored k-means centers. It is much farther from every center than any training customer was. Which statements are valid?", "options": ["Assigning a new customer changes the original unlabeled clustering into a supervised classification fit", "The assignment proves that it is a typical member of that group", "The nearest-center rule can still assign it to a cluster", "Its unusual distance warrants checking whether the learned representation covers this case"]}, {"id": "Q3-30", "topic": "M10", "type": "multi", "stem": "Two infection models have different ROC curves. Model A has a larger AUC; at the clinic's chosen operating thresholds, model B has lower expected decision cost. Which conclusions are justified?", "options": ["Threshold choice and error consequences need consideration beyond AUC", "Larger AUC guarantees the lower cost at every threshold and prevalence", "The clinic can favor B under its stated operating costs", "AUC summarizes ranking across positive and negative cases"]}, {"id": "Q3-31", "topic": "M3", "type": "single", "stem": "The same patient's measurements appear in both training and validation, although deployment targets new patients. What is the concern?", "options": ["The response becomes unsupervised", "All measurements must be discarded", "Validation can benefit from patient-specific overlap", "This guarantees pessimistic validation"]}, {"id": "Q3-32", "topic": "M7", "type": "multi", "stem": "A time series has roughly stable mean and variability, while another has a strong upward trend. Which statements match the lecture's stationarity discussion?", "options": ["One difference guarantees suitability for every possible time series", "Whether differencing helps should be assessed rather than assumed", "Differences may make some trending series more stable", "The stable series better resembles the lecture's stationary-data description"]}, {"id": "Q3-33", "topic": "M7", "type": "multi", "stem": "A level-only smoothing model and Holt give the same current level. The series has an estimated positive trend. Which statements about their ordinary forecasts are correct?", "options": ["Single smoothing acquires an explicit trend state merely by raising alpha", "A positive trend forecast identifies the operational cause of the rising response", "Holt can extend the estimated trend over the forecast horizon", "Level-only smoothing gives a flat point forecast at its current level"]}, {"id": "Q3-34", "topic": "M10", "type": "multi", "stem": "Which are valid reasons for pruning or limiting a tree?", "options": ["Children would have too few observations", "A split's training improvement does not persist on validation", "Complexity encourages fitting noise", "Every deeper tree is guaranteed to improve future prediction"]}, {"id": "Q3-35", "topic": "M5", "type": "multi", "stem": "Which circumstances can generate a genuine outlying record?", "options": ["A transcription error known to have changed the recorded value", "A one-time publicity event affecting sales", "A rare weather-related delivery disruption", "Natural tail variation in a large sample"]}, {"id": "Q3-36", "topic": "M6", "type": "single", "stem": "Upper CUSUM is reset when its raw cumulative value becomes negative. What purpose does this serve?", "options": ["It estimates a seasonal factor", "It avoids carrying downward evidence that delays a later upward alarm", "It makes false alarms impossible", "It proves the process mean has changed"]}, {"id": "Q3-37", "topic": "M7", "type": "single", "stem": "A forecaster supplies expected returns. A risk manager instead asks how large their fluctuations may be during a volatile period. Which method most directly serves that second target?", "options": ["CUSUM, because a change alarm is itself the variance forecast", "Logistic regression, because a binary-event probability is the same quantity as return variance", "GARCH, because its primary output is time-varying variance", "K-means, because groups of historical returns automatically give tomorrow's variance"]}, {"id": "Q3-38", "topic": "M6", "type": "multi", "stem": "Which quantities should remain distinct in a CUSUM analysis?", "options": ["Baseline expectation mu", "Per-observation allowance C", "Number of features as a mandatory synonym for T", "Cumulative alarm threshold T"]}, {"id": "Q3-39", "topic": "M8", "type": "multi", "stem": "When comparing AIC or BIC scores, which precautions matter?", "options": ["Assume raw scores from arbitrarily transformed response scales are automatically comparable", "Use comparable observations and likelihood definitions", "Prefer smaller values for the stated criteria", "Count parameters consistently"]}, {"id": "Q3-40", "topic": "M9", "type": "single", "stem": "A positive response is transformed with Box-Cox before regression. The fitted model now predicts transformed values. Which reporting practice is defensible at the survey level?", "options": ["Read a coefficient on the transformed scale as an identical raw-unit change without checking", "Identify the transformed response and explain how predictions relate to the original units before making operational claims", "Use the original response units for the transformed predictions without any conversion", "Claim the transformation proves all omitted variables are irrelevant"]}, {"id": "Q3-41", "topic": "M4", "type": "multi", "stem": "Which statements distinguish clustering from classification?", "options": ["A cluster label must have a known causal meaning", "A new point can be assigned to a discovered cluster without known response", "Clustering discovers groups from feature similarity", "Classification learns from known response categories"]}, {"id": "Q3-42", "topic": "M1", "type": "multi", "stem": "Which concerns should guide the choice between an interpretable regression and a forest?", "options": ["Need to explain individual modeled relationships", "Whether decision-makers can use the output", "Held-out predictive performance", "Which method has the most impressive name"]}, {"id": "Q3-43", "topic": "M8", "type": "single", "stem": "A binary predictor is one for premium members and zero otherwise. In an additive model its coefficient is 7. What is its interpretation?", "options": ["Premium membership is associated with a seven-unit predicted response difference holding other predictors fixed", "There must be seven membership categories", "The intercept must be seven", "Premium members have seven times the probability"]}, {"id": "Q3-44", "topic": "M3", "type": "multi", "stem": "Which statements about training and validation randomness are correct?", "options": ["Validation removes all randomness from measured quality", "A fitted model can capture accidental training patterns", "A validation winner can benefit from accidental validation patterns", "A separate test set reduces selection-related optimism"]}, {"id": "Q3-45", "topic": "M9", "type": "single", "stem": "A response is detrended as r=y-(10+2*t). At t=5 a model predicts r=3. What original-scale response is predicted?", "options": ["3", "13", "23", "-17"]}, {"id": "Q3-46", "topic": "M2", "type": "tf", "stem": "A linear SVM score of 2.3 is automatically a predicted probability of 2.3.", "options": []}, {"id": "Q3-47", "topic": "M3", "type": "blank", "stem": "In six-fold CV, each non-test observation serves as a validation observation ____ time(s).", "options": []}, {"id": "Q3-48", "topic": "M6", "type": "tf", "stem": "A larger CUSUM threshold usually requires more accumulated evidence before an alarm.", "options": []}, {"id": "Q3-49", "topic": "M8", "type": "blank", "stem": "The regression residual for observed y=12 and fitted y=9 is ____.", "options": []}, {"id": "Q3-50", "topic": "M10", "type": "blank", "stem": "With actual positive prevalence .1, sensitivity .8, and specificity .9, expected TP per 1,000 observations is ____.", "options": []}], [{"id": "Q4-01", "topic": "M8", "type": "multi", "stem": "An analyst says the maximum-likelihood fit chooses parameters that make the observed data most compatible with the assumed statistical model. Another says it chooses parameters that make every future outcome certain. Which statements are valid?", "options": ["The first description reflects the purpose of maximum-likelihood fitting", "A high likelihood makes all future observations deterministic", "Improved likelihood alone can justify unlimited increases in model complexity", "The likelihood calculation depends on the specified model and assumptions"]}, {"id": "Q4-02", "topic": "M9", "type": "single", "stem": "A regression is fit using two principal components instead of two original, correlated predictors. A manager wants to interpret one fitted component slope as the effect of changing only the first original predictor. What is the best response?", "options": ["A regression on components cannot produce predictions", "PCA components prove independent causal effects of original variables", "Every component is just the original feature with the largest mean", "A component combines original predictors, so its coefficient cannot automatically be read as the effect of one original feature alone"]}, {"id": "Q4-03", "topic": "M9", "type": "single", "stem": "A PCA transformation has been learned from training predictors. A new production case needs a regression prediction in that component space. Which procedure is appropriate?", "options": ["Use the new case's response to choose which component to retain before predicting it", "Fit a new PCA to the single new case so its axes are tailored to that prediction", "Substitute an original raw feature for a component because they necessarily share the same scale", "Apply the stored centering/scaling and loadings, then use the fitted component-space regression"]}, {"id": "Q4-04", "topic": "M6", "type": "multi", "stem": "Two CUSUM definitions of a hot season give different results. The analyst selects the definition supporting a preferred conclusion, hides the other analysis, and attributes the shift to a policy. Which concerns are warranted?", "options": ["Selecting only a favorable definition can bias the reported conclusion", "A transparent analysis distinguishes a detected change from its explanation", "Results should disclose relevant definitions and sensitivity to them", "The alarm itself identifies the policy as the causal mechanism"]}, {"id": "Q4-05", "topic": "M2", "type": "single", "stem": "A hard-margin linear SVM is proposed for labeled observations whose classes overlap in the available predictor space. The team insists that every training observation must lie on the correct side with a nonzero margin. What is the most sensible lecture-level response?", "options": ["Switching labels from 0/1 to -1/+1 removes overlap in the predictors", "Any labeled dataset has a perfect linear separation if its sample is large enough", "The strict hard-margin requirement may be infeasible; consider a soft-margin tradeoff and validate the resulting classifier", "A failed hard-margin fit proves the labels are all measurement errors"]}, {"id": "Q4-06", "topic": "M7", "type": "single", "stem": "A level-only smoothing model has current estimate 73. A colleague forecasts 73 tomorrow and 83 five observations ahead because the horizon is longer. No trend component has been fitted. Which statement is correct?", "options": ["The ordinary point forecasts remain 73 at both horizons; a systematic trend extension requires a trend-capable specification", "A flat point forecast means future observations have no variability", "A longer horizon must always produce a larger expected response", "Every smoothing model automatically adds two units per future observation"]}, {"id": "Q4-07", "topic": "M10", "type": "multi", "stem": "Default is labeled positive. For the same fixed logistic scores, the bank raises the classification threshold from .2 to .7. Which consequences are generally expected?", "options": ["The set of positive predictions can only shrink or stay the same", "False positives can fall, while false negatives can rise", "The fitted probabilities themselves must rise to compensate", "The change is automatically better without considering error costs"]}, {"id": "Q4-08", "topic": "M8", "type": "multi", "stem": "Two regression predictors move almost together across the data. The fitted model predicts reasonably well, but their individual coefficients change substantially when the sample changes slightly. Which conclusion is defensible?", "options": ["PCA can be considered as a representation change, but it will not establish causal importance", "The larger coefficient must always be the more causally important predictor", "The predictors provide overlapping information, so separate coefficient interpretations can be unstable even when predictions remain useful", "Prediction quality proves the two predictors have independently identified causal effects"]}, {"id": "Q4-09", "topic": "M7", "type": "single", "stem": "A Holt model's current trend is positive, while recent observations alternate in a repeatable weekly pattern around that trend. Which model-structure conclusion is reasonable?", "options": ["Increasing beta alone creates seven separate weekday effects", "Any positive trend implies every later observation exceeds the previous one", "The weekly pattern proves that trend estimation is impossible", "A trend component does not by itself model repeating seasonal phases; a seasonal specification may be needed"]}, {"id": "Q4-10", "topic": "M3", "type": "single", "stem": "Two equally good candidate methods obtain validation accuracies .81 and .85 due partly to sampling noise. Why may the chosen .85 overstate quality?", "options": ["Training data cannot contain random patterns", "Accuracy must always be exactly .5", "Selecting the winner favors favorable validation fluctuations", "The validation set has no labels"]}, {"id": "Q4-11", "topic": "M7", "type": "multi", "stem": "A reliability analysis uses multiplicative seasonality. Early-batch items have factor .8, later items 1.2, and the response is hours of operation before first breakdown. Which statements are supported?", "options": ["The early factor proves that workers are still learning the job at batch start", "Early-batch response levels are lower relative to the current baseline", "The seasonal pattern does not by itself determine the cause", "Higher hours before breakdown correspond to longer observed reliability"]}, {"id": "Q4-12", "topic": "M3", "type": "multi", "stem": "Which uses of test data preserve its final evaluation role?", "options": ["Compute a previously selected evaluation metric", "Apply a locked preprocessing transformation", "Inspect errors and choose a new kernel using test labels before reporting the old test score", "Apply the already selected model"]}, {"id": "Q4-13", "topic": "M6", "type": "multi", "stem": "An upper CUSUM statistic updates to exactly 10. The written alarm rule is S>T with threshold T=10. A manager treats equality as an alarm and claims a defect cause has been proved. Which statements are correct?", "options": ["The allowance and the alarm threshold are different quantities and should not be confused", "A different rule using S>=T would have different boundary behavior", "Either rule directly establishes the cause of the process change", "Equality does not trigger this particular strict-inequality rule"]}, {"id": "Q4-14", "topic": "M2", "type": "single", "stem": "An organization has labeled numeric outcomes and wants to predict a new case from similar historical cases. Three nearest responses are 4, 10, and 13. Which distinction is correct?", "options": ["The predicted value of 9 guarantees the new case has response 9", "k-means and k-NN regression are interchangeable because each uses k", "Both variants must return whichever response value is most frequent", "k-NN regression predicts their average, 9; k-NN classification would vote on category labels instead"]}, {"id": "Q4-15", "topic": "M8", "type": "multi", "stem": "Which residual plots suggest different modeling issues?", "options": ["A normal-looking raw predictor histogram proves every regression assumption", "Long same-sign runs over time can suggest serial dependence", "Systematic curvature can suggest wrong functional form", "A funnel can suggest nonconstant error variance"]}, {"id": "Q4-16", "topic": "M8", "type": "multi", "stem": "A straight-line regression misses a clear curved response pattern. A polynomial term or regression spline improves held-out prediction. Which statements are defensible?", "options": ["Any curvature requires a classification model rather than regression", "The improvement proves which physical mechanism caused the curvature", "A regression can include nonlinear functions of predictors while remaining linear in its fitted coefficients", "A spline can join different polynomial pieces smoothly"]}, {"id": "Q4-17", "topic": "M4", "type": "multi", "stem": "Which behaviors are expected within a standard k-means run under its squared-distance objective?", "options": ["The objective need not reach the global optimum", "Updating a nonempty cluster to its mean cannot increase its assigned-point SSE", "The objective increases every time the centers are recomputed", "Assigning points to closest centers cannot increase WSS"]}, {"id": "Q4-18", "topic": "M9", "type": "multi", "stem": "A team replaces original features with PCA components before regression and retains only a few components. Which statements are defensible?", "options": ["Loadings describe combinations of the original features", "The retained fraction of predictor variance equals the regression's response variance explained", "The component representation may make original-feature interpretation harder", "Dropping components can discard information useful for predicting the response"]}, {"id": "Q4-19", "topic": "M1", "type": "single", "stem": "A retailer summarizes spending patterns by customer group, predicts next-month spending, and allocates marketing under a fixed budget. Which distinction is correct?", "options": ["A descriptive relationship is automatically a causal effect of advertising", "A spending forecast alone determines the best marketing allocation without costs or constraints", "All three are unsupervised clustering tasks because they concern customers", "Summary, prediction, and constrained allocation address descriptive, predictive, and prescriptive questions respectively"]}, {"id": "Q4-20", "topic": "M4", "type": "multi", "stem": "Which goals can clustering support in the lectures?", "options": ["Learning a known yes/no response without using that response", "Targeted marketing segments", "Initial investigation of different subpopulations", "Geographic facility placement"]}, {"id": "Q4-21", "topic": "M7", "type": "multi", "stem": "Which statements distinguish smoothing from forecasting?", "options": ["A current smoothed level can use the current observed value", "Scoring a smoothed value as if it were an advance forecast can be optimistic", "Future observations may be used whenever smoothing coefficients are below one", "A forecast for the current value must be produced before observing it"]}, {"id": "Q4-22", "topic": "M1", "type": "multi", "stem": "A model for tomorrow's staffing uses tomorrow's realized queue length as a predictor and achieves excellent validation error. The decision is made tonight. Which statements are warranted?", "options": ["A valid evaluation should reproduce the information available when staffing is chosen", "Excellent retrospective error can therefore misrepresent feasible deployment performance", "Changing from regression to random forest necessarily repairs the information timing", "The predictor is unavailable at decision time"]}, {"id": "Q4-23", "topic": "M6", "type": "multi", "stem": "Which conclusions are supported by a CUSUM alarm?", "options": ["Accumulated evidence has crossed the chosen threshold", "A false alarm remains possible", "The evidence is consistent with a shift relative to the baseline", "The cause of the shift is proven"]}, {"id": "Q4-24", "topic": "M2", "type": "multi", "stem": "A fraud classifier deliberately shifts its decision boundary so more borderline cases are investigated. Missed fraud is expensive, while investigations also consume resources. Which statements follow?", "options": ["More true fraud may be caught, but unnecessary investigations can also increase", "The change should be evaluated using the relevant consequences of both error types", "Shifting a boundary is a decision tradeoff rather than proof that the probability of fraud changed", "Catching more fraud proves that the new boundary minimizes total cost"]}, {"id": "Q4-25", "topic": "M10", "type": "multi", "stem": "A classification tree has leaves with 18 of 20, 14 of 20, and 1 of 1 training cases classified correctly. A colleague averages the three percentages and uses the resulting high value to prove deployment quality. Which statements identify the errors?", "options": ["The one-case leaf is a potential overfitting warning", "Training accuracy should weight leaves by their case counts, giving 33/41", "Even correctly computed training accuracy is not independent deployment evidence", "Percentages from differently sized leaves must be weighted by their case counts for overall accuracy"]}, {"id": "Q4-26", "topic": "M5", "type": "multi", "stem": "A medicine-delivery dataset contains real rare delays caused by storms. Which approaches can preserve relevant risk?", "options": ["Assess how excluding delays changes operational optimism", "Model disruption probability separately from ordinary delivery duration", "Retain delays if the target includes such conditions", "Discard all delays merely because they are inconvenient to fit"]}, {"id": "Q4-27", "topic": "M7", "type": "multi", "stem": "Which are legitimate distinctions between ARIMA and GARCH?", "options": ["GARCH primarily models conditional variance", "GARCH uses squared shocks in its variance recursion", "ARIMA primarily models the conditional level/mean", "GARCH must include a differencing order d identical to ARIMA"]}, {"id": "Q4-28", "topic": "M5", "type": "single", "stem": "A boxplot flags a delivery delay, and a regression also gives it a large residual. The delay is verified as real and caused serious medicine spoilage. Which handling best matches the target of predicting delivery risk?", "options": ["Remove it because any boxplot flag establishes a recording error", "Use the large residual to prove the regression includes all relevant context", "Remove it because rare delays cannot matter to future risk", "Investigate and retain or appropriately represent the real risk rather than deleting it solely to improve fit"]}, {"id": "Q4-29", "topic": "M2", "type": "multi", "stem": "A min-max scaler is trained on values from 0 to 10. Which statements about future x=15 are correct?", "options": ["It lies outside the original training range", "Min-max fitting did not guarantee bounds for all future observations", "It must be silently clipped to one in every application", "Its transformed value is 1.5"]}, {"id": "Q4-30", "topic": "M3", "type": "multi", "stem": "Which statements about k-fold CV follow from its construction?", "options": ["Average scores can compare candidate settings", "Each fit excludes the held-out fold's outcomes from training", "Final deployment must use k different models even when no ensemble was intended", "Every fold is held out in turn"]}, {"id": "Q4-31", "topic": "M10", "type": "single", "stem": "A forest's importance chart ranks a predictor highly. A manager says increasing that predictor must increase the response by a fixed amount and cause an improvement. Which correction is most appropriate?", "options": ["A predictive model's importance ranking identifies the true physical causes", "Every high-importance predictor can be changed freely without constraints", "Importance is identical to a positive regression coefficient in original units", "Importance indicates predictive contribution under that fitted procedure; it need not give a signed linear effect or establish a causal intervention effect"]}, {"id": "Q4-32", "topic": "M9", "type": "multi", "stem": "Which statements about Box-Cox and regression assumptions are correct?", "options": ["Lambda is a transformation parameter", "Normality relevant to conventional regression inference concerns errors conditional on predictors", "A normal raw-response histogram guarantees equal conditional variance", "The standard Box-Cox family requires positive input values"]}, {"id": "Q4-33", "topic": "M2", "type": "multi", "stem": "A team changes income units from dollars to thousands of dollars. It keeps an unscaled k-NN distance rule otherwise unchanged and compares it with a tree using equivalent rescaled thresholds. Which statements are reasonable?", "options": ["An equivalent monotone rescaling preserves the ordering relevant to a tree threshold", "Both fitted procedures must change in exactly the same way", "The change can alter the relative weight of income in unscaled neighbor distances", "The transformation should be applied consistently to training and new observations"]}, {"id": "Q4-34", "topic": "M10", "type": "multi", "stem": "Which statements about ordinary trees and model trees are accurate?", "options": ["Leaf-specific regressions require enough observations to estimate coefficients", "A model tree can fit a separate regression within a leaf", "Ordinary regression CART often uses a constant leaf mean", "Every ordinary regression tree must fit every slope at each leaf"]}, {"id": "Q4-35", "topic": "M2", "type": "multi", "stem": "For overlapping training classes, which statements about soft-margin SVM are reasonable?", "options": ["Some violations can be accepted", "Class-specific loss multipliers can reflect asymmetric costs", "Violations are balanced against margin regularization", "The optimization must always become infeasible"]}, {"id": "Q4-36", "topic": "M3", "type": "single", "stem": "A dataset includes ordinary and holiday operations. A random split happens to place nearly all holiday cases in training, while the model will be deployed on both types. Which conclusion is supported?", "options": ["Using more predictors automatically supplies missing holiday evidence in validation", "The holiday cases should be deleted because they complicate the split", "The validation set may inadequately represent deployment, so its score should be interpreted with that coverage concern", "Any random split guarantees representative subgroups"]}, {"id": "Q4-37", "topic": "M7", "type": "single", "stem": "A forecast team has only a short, noisy demand history and asks whether an ARIMA model is automatically preferable to exponential smoothing because it is more general. Which response best reflects the survey lecture?", "options": ["More lag parameters make scarce observations irrelevant", "ARIMA must dominate smoothing on every series because it has more options", "GARCH supplies demand values whenever ARIMA lacks data", "Generality does not ensure a better forecast; data amount, behavior, and validation should guide the comparison"]}, {"id": "Q4-38", "topic": "M7", "type": "multi", "stem": "Which choices must be distinguished when specifying Holt-Winters?", "options": ["Cycle length in observations", "Additive versus multiplicative seasonal form", "Number of response categories as the seasonal parameter", "Observation frequency"]}, {"id": "Q4-39", "topic": "M10", "type": "single", "stem": "A call-center model predicts the number of arrivals in an interval from time of day and holiday status. Which introduced regression family naturally models this count mean?", "options": ["PCA without a response", "Poisson regression", "Hard-margin SVM", "Binary logistic regression only"]}, {"id": "Q4-40", "topic": "M10", "type": "multi", "stem": "Which conclusions are justified by ROC AUC=.9?", "options": ["The scores have strong positive-versus-negative ranking under the evaluation distribution", "It proves predicted probabilities are perfectly calibrated", "It specifies neither a deployment threshold nor its cost", "It means exactly 90% accuracy at every threshold"]}, {"id": "Q4-41", "topic": "M4", "type": "multi", "stem": "A k-means segmentation uses distance squared=4*(income difference squared)+(age difference squared) after representing both features on agreed scales. A manager calls the weights learned regression effects. Which statements are correct?", "options": ["The weights define similarity, not coefficients of a supervised response model", "The weight of four proves that changing income causes four times as much response change", "Increasing the income weight guarantees a more useful customer segmentation", "The stated weighting makes income differences contribute more to this distance than equal-sized age differences"]}, {"id": "Q4-42", "topic": "M2", "type": "multi", "stem": "Which statements about k-NN model behavior are correct?", "options": ["Its distance definition can change the selected neighbors", "It learns the same separating hyperplane as SVM by definition", "It stores/usefully retains labeled examples for prediction", "Increasing k may smooth local variation"]}, {"id": "Q4-43", "topic": "M8", "type": "single", "stem": "Two candidate models have similar fit on the same observations. BIC prefers the simpler one more strongly than AIC does. Which interpretation is defensible?", "options": ["BIC is a direct measure of classification accuracy", "The criteria use different complexity penalties; disagreement does not require a computation error", "The simpler model is proved to be the causal truth", "AIC and BIC must always rank models identically"]}, {"id": "Q4-44", "topic": "M7", "type": "multi", "stem": "A team has 12 historical observations but wants an ARIMA specification with many value and error lags. It treats the lecture's approximate 40-observation guidance as an absolute law. Which statements are appropriate?", "options": ["Reaching 40 observations guarantees the model and chosen lag orders are adequate", "A simpler model and realistic validation may be sensible alternatives", "The guidance is a rule of thumb rather than a universal guarantee or prohibition", "The very short history and flexible specification raise a legitimate estimation and overfitting concern"]}, {"id": "Q4-45", "topic": "M4", "type": "single", "stem": "A cluster-based service plan assigns a remote new demand point to the least-distant existing center. The manager concludes the current facility can serve it within the required response time. What is the best correction?", "options": ["Nearest-center assignment guarantees compliance with every operational constraint", "Nearest among existing centers does not imply close enough for the service standard; coverage must be evaluated separately", "A cluster ID directly supplies the travel time without a travel model or measurement", "The assignment proves that the new point was part of the training data"]}, {"id": "Q4-46", "topic": "M4", "type": "tf", "stem": "Permuting the names of clusters changes WSS when centers and memberships stay the same.", "options": []}, {"id": "Q4-47", "topic": "M6", "type": "blank", "stem": "For upper CUSUM with previous statistic=0, observation=18, baseline=12, and allowance=2, the new statistic is ____.", "options": []}, {"id": "Q4-48", "topic": "M7", "type": "tf", "stem": "A seasonal multiplicative factor below one necessarily reveals why that seasonal pattern occurs.", "options": []}, {"id": "Q4-49", "topic": "M9", "type": "blank", "stem": "If PCA eigenvalues are 5,3,2, the first component's predictor-variance fraction is ____.", "options": []}, {"id": "Q4-50", "topic": "M10", "type": "blank", "stem": "With TP=20,FN=5,FP=15,TN=60, specificity equals ____.", "options": []}], [{"id": "Q5-01", "topic": "M9", "type": "multi", "stem": "A team clusters unlabeled customers and also fits a repayment classifier using known outcomes. It proposes using PCA learned on the full dataset before evaluating either procedure. Which statements distinguish the tasks and evaluation issue?", "options": ["A learned PCA representation intended for predictive evaluation should be fitted within the training procedure", "Clustering discovers feature-based groups, while classification learns from outcome labels", "Cluster names are automatically repayment labels", "The absence of response labels in PCA means it cannot affect the evaluation pipeline"]}, {"id": "Q5-02", "topic": "M5", "type": "multi", "stem": "A verified demand spike came from a unique publicity event. A team wants forecasts for ordinary weeks, while another team wants emergency capacity planning that includes rare surges. Which handling is defensible?", "options": ["The ordinary-week model's error cannot be presented as performance for all weeks without qualification", "Its removal can be justified only by checking validity and target relevance, not by a better fitted score alone", "Every rare event should be deleted from both analyses", "The event's relevance can differ between the two target questions"]}, {"id": "Q5-03", "topic": "M5", "type": "multi", "stem": "Which questions should precede outlier handling?", "options": ["Which deletion maximizes training R-squared regardless of reality?", "What generated its unusual value?", "Is the record valid?", "Must the intended predictions or decisions cover that circumstance?"]}, {"id": "Q5-04", "topic": "M8", "type": "single", "stem": "A regression with many fitted parameters looks excellent on a small dataset. A corrected information criterion penalizes it more than uncorrected AIC. Which interpretation is appropriate?", "options": ["The correction supplies new observations that were not collected", "The lower training error alone proves the corrected criterion is wrong", "The correction addresses the finite-data situation and can discourage over-complex fitting", "A complexity criterion removes all need for validation or checking model assumptions"]}, {"id": "Q5-05", "topic": "M4", "type": "multi", "stem": "A hospital groups patient pickup locations with k-means to propose transport hubs. Some routes require crossing a river at a bridge. It then uses a classifier to predict whether each patient needs urgent pickup. Which statements separate the roles correctly?", "options": ["The classifier needs known urgency outcomes or labels for training", "The cluster with the largest coordinate values must be the urgent class", "Clustering can suggest geographic groups, but route constraints still matter to hub placement", "Distance-based grouping by itself proves which patients are medically urgent"]}, {"id": "Q5-06", "topic": "M4", "type": "multi", "stem": "Which statements about a cluster-based facility plan are correct?", "options": ["The number of facilities can constrain k", "Minimum WSS automatically satisfies every operational constraint", "A center is an analytical candidate, not automatically a feasible building site", "Coverage and travel constraints may require additional analysis"]}, {"id": "Q5-07", "topic": "M10", "type": "single", "stem": "A regression tree considers a split into a two-case child and an eighteen-case child. The two-case child has no training variation, and total training error falls slightly. Which reasoning best follows the lecture?", "options": ["Any split reducing training error must be retained", "Both children count equally regardless of size when measuring the total fit", "The zero variation in two cases proves the new leaf will generalize perfectly", "Assess improvement and adequate child support, then validate or prune; the tiny perfect leaf is not sufficient evidence of usefulness"]}, {"id": "Q5-08", "topic": "M7", "type": "multi", "stem": "Reliability is measured as operating hours before failure for each successive manufactured item; production batches contain 150 items. Which interpretations are supported?", "options": ["A seasonal factor .7 at a phase represents a lower proportional response", "Cycle length can be 150 observations", "A positive trend proves the training policy caused improvement", "A positive trend means modeled reliability response rises over successive items"]}, {"id": "Q5-09", "topic": "M9", "type": "multi", "stem": "Two standardized predictor columns are exact duplicates. PCA is used before regression. Which statements are reasonable?", "options": ["Duplicated predictors establish two independent causal effects", "Keeping the first component can summarize the shared predictor information", "The second direction has no additional variation beyond the first", "The first component therefore guarantees a perfect response prediction"]}, {"id": "Q5-10", "topic": "M3", "type": "single", "stem": "Eight-fold validation on 1,600 non-test observations selects a regression specification. The final test set has not been used. Which fitting plan reflects the lecture approach?", "options": ["Refit the chosen specification on all 1,600 non-test observations and then evaluate once on the untouched test set", "Average fold coefficients automatically because cross-validation requires that final estimator", "Fit the final model on only the 200 observations from the best validation fold", "Use the final test responses to select a different predictor subset before reporting the same test score"]}, {"id": "Q5-11", "topic": "M1", "type": "multi", "stem": "Which features make a modeling conclusion useful and defensible?", "options": ["Its limitations and assumptions are understood", "It answers the actual operational question", "It respects the information and population represented by the data", "It agrees with the analyst's initial belief regardless of the evidence"]}, {"id": "Q5-12", "topic": "M3", "type": "multi", "stem": "The team compares SVM, k-NN, and a tree on a training/validation split. Before splitting, it selects features by checking their relationships with all response labels. Which statements identify the concern?", "options": ["The validation outcomes influenced feature selection", "Using several model families does not repair that leakage", "Every later validation score is guaranteed to be an unbiased final estimate because coefficients were fitted only on training cases", "Feature selection should be part of the training and validation procedure rather than use the held-out labels beforehand"]}, {"id": "Q5-13", "topic": "M7", "type": "single", "stem": "A volatility model reports high variance after a quiet latest observation because earlier volatility was high. A manager says zero latest signed error must force zero variance. Which correction fits GARCH's lecture-level mechanism?", "options": ["Every positive variance implies the next return is positive", "Lagged variance as well as squared errors can carry volatility forward; a quiet new observation need not erase it", "GARCH obtains changing variance by differencing the variance exactly like ARIMA differences observations", "Variance depends only on the sign of the latest error"]}, {"id": "Q5-14", "topic": "M7", "type": "single", "stem": "A multiplicative seasonal factor is estimated at 1.2 for the current phase of a production cycle. The team instead proposes an additive seasonal term of +1.2 in the same response units without refitting. Which statement is correct?", "options": ["The two quantities mean different things: a multiplicative factor rescales the baseline, while an additive effect is an amount on the response scale", "Both always produce the same forecast for any baseline", "A factor above one proves the cause of the seasonal effect", "The factor says every observation in that phase equals exactly 1.2"]}, {"id": "Q5-15", "topic": "M7", "type": "multi", "stem": "Monthly output increases roughly linearly, while its first differences appear much more stable. A team proposes differencing and then an ARIMA model; another proposes a trend component in smoothing. Which conclusions are defensible?", "options": ["The stable first differences prove the physical cause of the growth", "The resulting candidate forecasts should be compared rather than declaring one universally best", "Increasing ARIMA d always improves the forecast without changing interpretation", "Differencing and explicit trend smoothing are different ways of representing temporal structure"]}, {"id": "Q5-16", "topic": "M4", "type": "multi", "stem": "At the same k, two k-means starts produce WSS=90 and WSS=100. For a larger k, another run produces WSS=60. Which comparisons are justified?", "options": ["Different starts can lead to different local solutions", "The larger-k run's lower WSS alone proves it is the best operational segmentation", "The minimum observed raw WSS automatically identifies the most useful k for deployment", "At the same k, the lower-WSS run is better under the stated training objective"]}, {"id": "Q5-17", "topic": "M10", "type": "single", "stem": "A calibrated probability model predicts p for a rare fault. False alarms cost $3, missed faults cost $9, and correct actions cost zero. At p=.30, which action has lower stated expected error cost?", "options": ["Declare no fault because .30 is below .50, regardless of consequences", "The choice is impossible because a probability cannot inform a decision", "Declare a fault: expected cost .70*3=$2.10 is less than .30*9=$2.70", "The actions must have the same expected cost because both use the same probability"]}, {"id": "Q5-18", "topic": "M2", "type": "single", "stem": "Two candidate neighbor rules have validation costs $12 and $8 per 100 decisions despite accuracies .95 and .90 respectively. If minimizing this measured cost is the objective, which is favored?", "options": ["The .90-accuracy rule with $8 cost", "The rule with more neighbors regardless of validation", "The .95-accuracy rule regardless of cost", "Neither because only accuracy is legal as a metric"]}, {"id": "Q5-19", "topic": "M7", "type": "multi", "stem": "A manufacturer records item position, production day, and operating hours before failure across fixed 150-item batches. Item position and production day are highly correlated. It wants to examine early-batch reliability. Which statements align the time-series and PCA roles?", "options": ["PCA of the two correlated predictors can summarize their shared variation before a factor-based regression", "PCA by itself determines why early items fail", "The batch's calendar duration replaces 150 even when the series advances once per item", "An item-indexed seasonal model uses reliability hours as the response and 150 as the cycle length"]}, {"id": "Q5-20", "topic": "M6", "type": "single", "stem": "An upper CUSUM starts at zero with baseline 10 and allowance 1. Three readings of 12 arrive. The threshold is 2 and the alarm rule is S>2. Which interpretation is correct?", "options": ["The alarm must occur on the first reading because 12 exceeds the baseline", "The statistics are 1, 2, and 3; the first alarm occurs on the third reading under this rule", "Each reading is tested independently, so accumulation has no effect", "The third reading proves a particular operator caused the change"]}, {"id": "Q5-21", "topic": "M9", "type": "multi", "stem": "An analyst has many correlated numerical measurements and proposes keeping a few leading PCA components before fitting a predictive model. Which statements fit the survey-level purpose and limits?", "options": ["PCA guarantees that no predictive information is lost whenever most predictor variance is retained", "The downstream model should be evaluated because PCA did not use the response to define its directions", "PCA itself chooses retained components by their relationship with the observed response labels", "PCA can reduce the number of coordinates while preserving much of the measured predictor variation"]}, {"id": "Q5-22", "topic": "M7", "type": "multi", "stem": "A response is usually positive but sometimes zero. The team plans multiplicative Holt-Winters updates that divide by a seasonal factor and current level. Which choices are defensible?", "options": ["Assume naming the method seasonal makes zero-related numerical issues impossible", "Treat multiplication and addition as interchangeable without changing the updates", "Consider whether a different seasonal representation better matches the response behavior", "Check whether the model's divisions and scale assumptions are suitable for these observations"]}, {"id": "Q5-23", "topic": "M10", "type": "multi", "stem": "A random forest outperforms one tree on validation, but both models were trained with a predictor recorded after the decision deadline. Which conclusions follow?", "options": ["Tree diversity does not repair unavailable-predictor leakage", "The forest's higher validation score establishes that it can be deployed at the stated decision time", "The candidate pipeline must be revised and reassessed using timely predictors", "Enough trees automatically create the missing pre-decision information"]}, {"id": "Q5-24", "topic": "M9", "type": "multi", "stem": "Which statements correctly contrast feature selection and feature extraction?", "options": ["Extraction can reduce dimension without selecting original columns directly", "PCA always chooses exactly one original variable as its first component", "Selection retains a subset of original variables", "PCA extraction constructs linear combinations"]}, {"id": "Q5-25", "topic": "M2", "type": "multi", "stem": "A clinic has binary infection labels and symptoms available at screening. It wants probabilities for risk communication, class decisions for triage, and an alarm if average symptom severity shifts over time. Which statements assign roles correctly?", "options": ["Logistic regression directly addresses infection probability from symptoms", "A class decision can use a chosen threshold on that probability", "CUSUM of ordered symptom measurements addresses the shift-detection request", "Clustering symptom measurements automatically gives calibrated infection probabilities without infection labels"]}, {"id": "Q5-26", "topic": "M7", "type": "multi", "stem": "Which contrasts between time-series methods are correct?", "options": ["Simple smoothing extrapolates a level without explicit trend", "Holt-Winters adds a repeating seasonal component", "GARCH's primary output is a list of unsupervised customer clusters", "Holt adds an evolving trend"]}, {"id": "Q5-27", "topic": "M2", "type": "single", "stem": "A linear classifier predicts positive for x1+x2>6. A case moves from (2,3) to (2,5). A manager attributes the resulting class change to a causal effect of increasing x2. Which interpretation is correct?", "options": ["Changing coordinates proves that all other conditions in the system stayed fixed", "The predicted class changes because the case crosses the rule, but that mathematical change is not proof of a causal effect in the real system", "The class cannot change because only one predictor moved", "The boundary gives a 100% probability of the positive event after the move"]}, {"id": "Q5-28", "topic": "M8", "type": "single", "stem": "A production regression finds an apparently useful negative association between speed and reliability. Its interval is wide and includes zero, and speed is correlated with batch conditions. Which reporting approach is defensible?", "options": ["Report the estimated direction and uncertainty, and avoid a causal recommendation unsupported by the design", "Treat the fitted negative coefficient as certain for every future batch", "Ignore the predictor correlation because the coefficient has a sign", "Report that speed has exactly no relationship because zero is in the interval"]}, {"id": "Q5-29", "topic": "M10", "type": "multi", "stem": "If class prevalence changes but sensitivity and specificity stay fixed, which metrics generally can change?", "options": ["Overall accuracy", "Precision", "Expected cost per observation", "Sensitivity by assumption"]}, {"id": "Q5-30", "topic": "M6", "type": "multi", "stem": "A safety monitor is retuned to alarm with less accumulated evidence. Missed developing faults are especially costly, but false alarms interrupt production. Which statements describe the tradeoff?", "options": ["The retuning guarantees no missed faults and no false alarms", "The threshold should be evaluated against both consequences", "A lower threshold can detect shifts sooner", "A lower threshold can also increase false alarms"]}, {"id": "Q5-31", "topic": "M7", "type": "multi", "stem": "A forecast model has an estimated rising trend, but a control engineer needs to flag a sudden increase relative to a stable reference. Which statements correctly separate the two goals?", "options": ["CUSUM directly accumulates evidence relative to the stated reference", "A positive fitted trend automatically identifies a sudden change date and its cause", "Holt can model level plus an evolving trend for forecasting", "The engineer should choose a baseline meaningful for the monitoring task rather than treating a forecasting output as the same decision"]}, {"id": "Q5-32", "topic": "M2", "type": "multi", "stem": "Which are distinct choices in a k-NN classification specification?", "options": ["Distance metric", "Number of lagged innovations as a required k-NN parameter", "Number of neighbors", "Feature scaling/weights"]}, {"id": "Q5-33", "topic": "M10", "type": "multi", "stem": "A cancer-screening classifier evaluates 1,000 people and produces TP=8, FN=2, FP=90, TN=900. Which statements are correct?", "options": ["The rare positive class makes accuracy alone an incomplete summary for this screening task", "The high accuracy makes the cost of missed cancers and follow-up tests irrelevant", "Accuracy is (8+900)/1000=.908", "Among positive predictions, 8/98 actually have cancer"]}, {"id": "Q5-34", "topic": "M10", "type": "multi", "stem": "A clinic expects disease prevalence .20. A model has sensitivity .75 and specificity .90. Missing disease costs $20, an unnecessary follow-up costs $1, and correct decisions are free. Which statements correctly translate this into expected error cost?", "options": ["Prevalence, both class-conditional error rates, and costs are needed for this population comparison", "The population false-negative fraction is .20*(1-.75)=.05", "The expected error cost per person is .05*20+.08*1=$1.08", "The population false-positive fraction is .80*(1-.90)=.08"]}, {"id": "Q5-35", "topic": "M8", "type": "multi", "stem": "Which can explain a correlation without a direct causal effect of x on y?", "options": ["A small p-value necessarily eliminates all alternatives", "Reverse causation", "Selection or omitted-variable structure", "A common cause affects both"]}, {"id": "Q5-36", "topic": "M1", "type": "multi", "stem": "A restaurant estimates arrival counts from time of day and holiday status, groups menu demand patterns, and decides purchase quantities under spoilage costs. Which statements assign methods or roles appropriately?", "options": ["The count forecast alone specifies the optimal purchase quantities under all costs", "K-means can group feature profiles without a labeled outcome", "Purchase decisions require the operational objective in addition to the predictive inputs", "Poisson regression can model an attribute-dependent arrival count rate"]}, {"id": "Q5-37", "topic": "M3", "type": "multi", "stem": "Why can a single holdout estimate vary materially across random splits?", "options": ["Each fit may change when its training subset changes", "Different splits allocate rare or influential cases differently", "Finite validation sets contain random variation", "The method eliminates all sources of randomness by definition"]}, {"id": "Q5-38", "topic": "M10", "type": "multi", "stem": "Four teams need a count rate from attributes, a smoothly varying numeric response, updated coefficient beliefs with few observations, and a numeric prediction from similar labeled records. Which pairings match the introduced methods?", "options": ["Regression splines can join polynomial pieces with smooth connections", "Poisson regression can address the attribute-dependent count rate", "k-NN regression averages nearby numeric responses without requiring one global straight-line equation", "Bayesian regression can combine starting coefficient distributions with observed data"]}, {"id": "Q5-39", "topic": "M2", "type": "multi", "stem": "A trained model is sensitive to a unit change from dollars to thousands of dollars. Which explanations can be relevant?", "options": ["An unadjusted distance metric changes its numerical geometry", "An unadjusted norm penalty can change its relative feature treatment", "Every algorithm is invariant to arbitrary feature units without any adjustment", "Consistent preprocessing can address the scale change"]}, {"id": "Q5-40", "topic": "M6", "type": "multi", "stem": "Which choices could reasonably improve the interpretation of a CUSUM study?", "options": ["Check sensitivity to plausible C and T values", "Treat one local alarm as proof of an unrelated national policy effect", "Report a narrow conclusion matching the measured outcome", "Use a baseline appropriate to the unchanged regime"]}, {"id": "Q5-41", "topic": "M8", "type": "multi", "stem": "A team models log(cost) instead of cost to improve a regression's behavior. The manager interprets an added unit of the transformed-response prediction as an added dollar of expected cost. Which concerns are warranted?", "options": ["The transformed response and raw-dollar response have different scales", "A transformation automatically proves the original response was measured incorrectly", "Predictive performance should be judged on a scale relevant to the application, not mislabeled units", "Reporting should explain how the fitted predictions relate to the original units"]}, {"id": "Q5-42", "topic": "M3", "type": "multi", "stem": "Which claims about a final test score are appropriate?", "options": ["It may fail to represent deployment after a substantial distribution shift", "It still has finite-sample uncertainty", "It estimates performance under the test sampling conditions", "It guarantees identical accuracy in every future population"]}, {"id": "Q5-43", "topic": "M4", "type": "multi", "stem": "Which interpretations of a large optimal WSS decrease are defensible?", "options": ["Adding a cluster improves feature-space fit", "The new group may merit substantive investigation", "Operational relevance can differ from mathematical improvement", "The result alone establishes a known response-category boundary"]}, {"id": "Q5-44", "topic": "M2", "type": "multi", "stem": "A clinic has labeled symptom records and needs an infection-positive or infection-negative class prediction for new patients. Which lecture approaches can be used for this classification task?", "options": ["k-means interpreted as a supervised classifier by definition", "Classification trees", "k-NN classification", "SVM"]}, {"id": "Q5-45", "topic": "M8", "type": "single", "stem": "A model with lower AIC predicts slightly worse on representative held-out cases than an alternative. Management's goal is the held-out decision cost, and the lower-AIC model also has higher cost. Which conclusion is defensible?", "options": ["Lower AIC guarantees lower cost for every decision rule", "The held-out comparison must be wrong whenever it disagrees with AIC", "AIC identifies the action with the largest business profit without an action model", "AIC is useful model-comparison evidence, but it does not override the stated operational objective and appropriate validation evidence"]}, {"id": "Q5-46", "topic": "M1", "type": "tf", "stem": "A model family, a predictor specification, and a fitted numerical equation can all be called a model in these lectures.", "options": []}, {"id": "Q5-47", "topic": "M2", "type": "blank", "stem": "Two soft-margin SVM settings fit training data differently. To select the setting for prediction, compare their ____ performance rather than training fit alone.", "options": []}, {"id": "Q5-48", "topic": "M5", "type": "tf", "stem": "A collective outlier must contain at least one individual value that is extreme without any context.", "options": []}, {"id": "Q5-49", "topic": "M7", "type": "blank", "stem": "ARIMA(p,d,q) uses p for ____ lags and q for ____ lags.", "options": []}, {"id": "Q5-50", "topic": "M10", "type": "blank", "stem": "A standard constant-response regression-tree leaf predicts the ____ of its training responses, whereas a classification leaf usually predicts the most common class.", "options": []}], [{"id": "Q6-01", "topic": "M5", "type": "single", "stem": "An attendance counter reports 20,21,20,21 repeatedly for hours, although real attendance normally varies irregularly. Every number is within the usual range. Which assessment is most defensible?", "options": ["The repeated pattern can be collectively anomalous despite ordinary individual values", "No anomaly is possible unless a value exceeds the historical maximum", "The repetition proves a particular hardware component failed", "A boxplot of the values must identify the faulty sequence"]}, {"id": "Q6-02", "topic": "M1", "type": "single", "stem": "A museum estimates the current number of visitors in uninstrumented rooms from sensors in other rooms. No future time is involved. How should the estimation task be classified?", "options": ["Unsupervised: a response cannot exist at the current time", "Prescriptive: every estimate automatically chooses an action", "Descriptive only: prediction must refer to tomorrow", "Predictive: it estimates an unknown response from available information"]}, {"id": "Q6-03", "topic": "M7", "type": "single", "stem": "A museum records one visitor total per month with a yearly cycle. While updating March, which old seasonal factor belongs in the ordinary same-phase update?", "options": ["The largest factor observed in any month", "The previous February factor solely because it is most recent", "The overall count of years", "The previous March factor"]}, {"id": "Q6-04", "topic": "M10", "type": "single", "stem": "Five forest classifiers predict exhibit classes A,A,B,C,C. The application expects one class. Which detail is required?", "options": ["An arithmetic mean of the letters", "A tie rule for the two tied plurality classes", "A numeric regression response in every training row", "A change to five-fold validation"]}, {"id": "Q6-05", "topic": "M8", "type": "single", "stem": "A huge visitor dataset estimates an extra .02 minutes of queue time per added sign with a very small p-value. Which response is most defensible?", "options": ["Assess whether the effect is operationally meaningful in addition to its statistical evidence", "Declare the association causal because the sample is large", "Interpret the p-value as the effect size in minutes", "Conclude the effect must save hours because the p-value is small"]}, {"id": "Q6-06", "topic": "M4", "type": "multi", "stem": "A k-means analysis represents reader locations. One reader is entered ten times while every other reader is entered once. Which statements are correct?", "options": ["Duplicate coordinates are automatically ignored by standard k-means", "Whether repeated visits or distinct readers are the target determines whether this weighting makes sense", "The duplication can pull a mean center toward that location", "That reader contributes repeatedly to the squared-distance objective"]}, {"id": "Q6-07", "topic": "M3", "type": "single", "stem": "A library checks a supposed final test score each time it changes a classifier and stops when the score improves. Which description fits that test collection now?", "options": ["Repeatedly checking it eliminates sampling uncertainty", "It is being used for selection, so it no longer gives an untouched final assessment", "It remains independent because the model parameters were fitted elsewhere", "It becomes a training fold only if its rows are physically copied"]}, {"id": "Q6-08", "topic": "M3", "type": "single", "stem": "An analyst converts every length from inches to centimeters using the exact known conversion before splitting records. Which interpretation is most defensible?", "options": ["A fixed unit conversion does not learn from held-out records in the way an estimated scaler does", "The conversion guarantees the model will generalize", "The conversion is equivalent to learning the entire dataset mean", "Every operation before splitting necessarily leaks labels"]}, {"id": "Q6-09", "topic": "M5", "type": "multi", "stem": "A model of museum ticket sales omits weekend effects. Large positive residuals occur on nearly every weekend. Which interpretations are warranted?", "options": ["The residual pattern motivates representing the omitted context", "Repeated weekend residuals establish that all weekend records are corrupted", "All weekends must be removed before any modeling", "Routine weekend observations should not be declared errors solely from these residuals"]}, {"id": "Q6-10", "topic": "M6", "type": "multi", "stem": "A CUSUM energy monitor uses a baseline from an empty building after the building opens to the public. Which conclusions are warranted?", "options": ["Normal occupancy differences can matter to interpretation", "Any alarm proves deterioration in equipment", "The empty-building reference remains appropriate for all occupied operation", "An alarm may reflect an inappropriate reference for the new operating condition"]}, {"id": "Q6-11", "topic": "M7", "type": "multi", "stem": "A ticketing team reports excellent prediction error by updating the level with today's sales and then calling that updated level a forecast of today's sales. Which statements are correct?", "options": ["The reported estimate uses information unavailable for an advance forecast", "Today's sales can be used in a forecast of today made yesterday", "The distinction between a fitted smoothed value and a prior forecast matters", "The same procedure establishes excellent advance forecast performance"]}, {"id": "Q6-12", "topic": "M8", "type": "multi", "stem": "Two exhibit forecasts have residuals +4 and -4. Which statements describe their fit summary?", "options": ["Zero residual sum means both forecasts were exact", "Their SSE is 32", "Their zero residual sum means their SSE is also zero", "Squaring prevents opposite errors from cancelling"]}, {"id": "Q6-13", "topic": "M4", "type": "single", "stem": "Two librarians report identical cluster memberships but number their clusters in opposite order. How should their segmentations be compared?", "options": ["Cluster 1 must represent the same demographic category in every run", "Numbering determines the nearest-center metric", "Match memberships and centers before treating label numbers as differences", "Opposite numbering proves one run has larger WSS"]}, {"id": "Q6-14", "topic": "M4", "type": "multi", "stem": "All coordinates in a Euclidean clustering problem are multiplied by 100, with corresponding initial centers also multiplied by 100. Which statements describe the equivalent exact run?", "options": ["Nearest-center comparisons are preserved", "The scaled centers can be converted back to the original solution", "Only the first feature becomes more important relative to the others", "WSS is multiplied by 10,000"]}, {"id": "Q6-15", "topic": "M6", "type": "single", "stem": "A building monitor sees many small above-baseline energy readings, none individually dramatic. Which method-feature pairing best explains why CUSUM may still signal?", "options": ["It computes a future mean using only the last reading", "It ranks rooms by static Euclidean clusters", "It requires one reading to be the largest ever observed", "It accumulates consistent directional deviations after an allowance"]}, {"id": "Q6-16", "topic": "M3", "type": "multi", "stem": "Each archival photograph yields ten cropped images. Deployment classifies entirely new photographs. A random crop split puts crops from every photograph into both fitting and evaluation. Which concerns apply?", "options": ["Evaluation can exploit similarity to the same source photograph", "Ten crops automatically create ten independent source photographs", "The split should reflect unseen photographs", "Keeping labels hidden for some crops necessarily removes shared-source information"]}, {"id": "Q6-17", "topic": "M8", "type": "multi", "stem": "Two comparable fitted models have AIC=-2*log-likelihood+2*K. Model A has log-likelihood -40 and K=3; B has -37 and K=7. Which statements are correct?", "options": ["B's higher likelihood does not overcome its larger penalty here", "AIC must be positive because its definition forbids negative values", "AIC(A)=83 because its three coefficients count once in the penalty", "AIC(B)=88"]}, {"id": "Q6-18", "topic": "M9", "type": "single", "stem": "A museum detrends a historical price response to study other relationships. Another analyst adjusts prices using a known inflation index. Which statement is most appropriate?", "options": ["The adjustment should reflect the intended baseline and available domain information; a straight time line is not the only possibility", "PCA by itself restores purchasing-power units", "All price trends are necessarily constant straight lines", "Differencing and an inflation adjustment are identical operations"]}, {"id": "Q6-19", "topic": "M10", "type": "multi", "stem": "A ticket-renewal logistic fit reports pseudo-R-squared .4. A manager interprets this as ordinary least-squares variance explained. Which statements are warranted?", "options": ["Pseudo-R-squared is not the predicted renewal probability of every visitor", "The output must have been fitted by ordinary least squares", "Do not substitute ordinary R-squared interpretation automatically", "Check the pseudo-R-squared definition"]}, {"id": "Q6-20", "topic": "M6", "type": "single", "stem": "Two monitors use the same baseline and allowance. One receives a persistent larger upward departure than the other. With equal thresholds, which statement is defensible?", "options": ["They must alarm simultaneously because their thresholds match", "Only sample count matters, not deviations", "A larger departure forces the threshold itself to change", "Larger positive increments can cross the threshold sooner, though exact behavior depends on the observed sequence"]}, {"id": "Q6-21", "topic": "M1", "type": "multi", "stem": "A public library wants an analytics model to make service better. Before choosing an algorithm, which questions most directly make that request modelable?", "options": ["Which measurable outcome or decision should improve?", "Which model currently has the longest name?", "The algorithm should be chosen before clarifying available inputs", "What tradeoffs define a useful improvement?"]}, {"id": "Q6-22", "topic": "M2", "type": "multi", "stem": "A library predicts whether a newly purchased book will need rebinding within a year. Which data roles fit a prediction made on purchase day?", "options": ["Whether rebinding occurs within the next year is the response label for historical books", "Purchase-time thickness is the historical future repair outcome", "Binding type is a possible predictor", "The number of repairs during that next year is a timely predictor"]}, {"id": "Q6-23", "topic": "M6", "type": "single", "stem": "An upper CUSUM has S=1, baseline 30, allowance 2, and reading 25. Using max(0,S+x-mu-C), what happens?", "options": ["It alarms automatically because the reading is below baseline", "It becomes 6 because all differences are absolute", "It remains 1 because only upward readings update it", "It resets to zero; it does not carry -6 forward"]}, {"id": "Q6-24", "topic": "M7", "type": "single", "stem": "With fixed single-smoothing alpha=.5, a one-time increase in an observation contributes through the next recursive level estimates. Which description is correct if later observations return to their original values?", "options": ["Its contribution halves at each subsequent update", "Its contribution remains fixed forever", "It disappears immediately after one update for every alpha", "Its contribution grows because the data are ordered"]}, {"id": "Q6-25", "topic": "M9", "type": "single", "stem": "A one-feature PCA representation subtracts training mean 10 and uses loading +1. A new observation is 13. Which quantity is its score in that centered coordinate?", "options": ["13", "3", "130", "10"]}, {"id": "Q6-26", "topic": "M4", "type": "single", "stem": "During k-means on reading-room coordinates, the analyst recomputes a center using all observations, including ones assigned to other clusters. What is the central correction?", "options": ["Each center update should average only its own assigned observations", "Center updates should use response labels", "The update should move to the farthest individual observation", "Every center should be the overall grand mean at every iteration"]}, {"id": "Q6-27", "topic": "M2", "type": "multi", "stem": "For an unweighted 3-NN classifier, the three closest historical manuscripts have labels genuine, genuine, forged. The closest genuine example is later verified to have a wrong response label and is relabeled forged. Which statements follow if distances stay fixed?", "options": ["The local vote changes to forged", "The set of nearest examples can stay unchanged", "This correction changes a response label rather than a distance coordinate", "Feature scaling must change before any label can change the vote"]}, {"id": "Q6-28", "topic": "M9", "type": "multi", "stem": "A PCA report flips a loading vector and all corresponding scores from positive to negative. The fitted component-regression slope is also negated. Which statements follow?", "options": ["Predictions from that component can be unchanged", "The direction describes the same geometric axis", "Its variance ranking is unchanged", "The flipped sign proves the original feature effect changed causally"]}, {"id": "Q6-29", "topic": "M5", "type": "multi", "stem": "An outdoor sensor records 28 degrees Celsius but its date was accidentally entered as a winter date. A seasonal baseline gives a large residual. Which actions make sense?", "options": ["Recognize that faulty context can make an ordinary value look anomalous", "Delete every observation at 28 degrees", "Check and correct the date if the original timestamp is recoverable", "Treat the large residual as proof the temperature sensor failed"]}, {"id": "Q6-30", "topic": "M3", "type": "multi", "stem": "Two document classifiers are evaluated on different collections: A on clean scans and B on damaged scans. A has higher accuracy. Which conclusions are justified?", "options": ["The difference confounds model and collection difficulty", "A is established as better on damaged scans", "Accuracy can be compared operationally without checking what cases were evaluated", "A common representative evaluation collection would support a clearer comparison"]}, {"id": "Q6-31", "topic": "M2", "type": "single", "stem": "An archive changes manuscript categories from codes 1,2,3 to 100,200,300 without changing the categories. A distance-based classifier changes predictions. What should be investigated first?", "options": ["Whether the true event probabilities must have tripled", "Whether the archive created new outcome information by renaming codes", "Whether arithmetic on these identifiers encodes an intended similarity", "Whether category 300 is necessarily three times category 100"]}, {"id": "Q6-32", "topic": "M7", "type": "single", "stem": "In Holt smoothing, the newest fitted level is 52, the previous level is 50, previous trend is 1, and beta=.25. Which trend update follows beta*(new level-old level)+(1-beta)*old trend?", "options": ["13.75", "52", "2", "1.25"]}, {"id": "Q6-33", "topic": "M3", "type": "multi", "stem": "Three validation folds have 10,10,80 records and respectively 0,0,20 classification errors. Which statements distinguish pooled error from an equal-fold average?", "options": ["Pooled error is 20/100", "Equal averaging of the three fold error rates gives a different number", "Unequal fold sizes make the choice of averaging convention relevant", "Pooled error gives the 80-record fold the same weight as a 10-record fold"]}, {"id": "Q6-34", "topic": "M10", "type": "single", "stem": "A constant-response tree leaf contains all book weights greater than 2 kg and predicts 6 repair hours. A new book weighs 10 kg and reaches that leaf. Which interpretation is correct?", "options": ["It fits a new slope using the new case alone", "It cannot assign cases outside the largest observed weight", "It predicts 30 because five times the weight requires five times the response", "The ordinary leaf still predicts 6; the constant tree does not extrapolate a within-leaf weight slope"]}, {"id": "Q6-35", "topic": "M10", "type": "single", "stem": "All predicted renewal probabilities are either below .3 or above .8. Moving the positive threshold from .4 to .6 yields what on these cases?", "options": ["More positives necessarily", "Identical class decisions despite a changed threshold", "Different fitted probabilities necessarily", "An undefined confusion matrix"]}, {"id": "Q6-36", "topic": "M1", "type": "multi", "stem": "A mathematical model recommends closing a library branch to reduce operating cost. The original request was to maintain neighborhood access within a spending limit. Which interpretations are warranted?", "options": ["The objective may have omitted access", "A minimum-cost result needs interpretation against the original request", "Access requirements could be represented as constraints or part of the objective", "Correct optimization of the written objective establishes that the request was satisfied"]}, {"id": "Q6-37", "topic": "M7", "type": "multi", "stem": "A lecture-style GARCH variance update receives a forecast error of -5 rather than +5, with the same prior variance and settings. Which statements are correct?", "options": ["The negative error cannot produce a negative variance contribution merely because of its sign", "The sign reversal alone must change the contribution from 25 to -25", "The update now forecasts the sign of tomorrow's response", "Both give the same squared-error contribution"]}, {"id": "Q6-38", "topic": "M10", "type": "single", "stem": "A renewal model operates at sensitivity .8 and specificity .9. Where is its point on the usual ROC axes?", "options": ["(0.2,0.9)", "(0.8,0.9)", "(0.1,0.8)", "(0.9,0.8)"]}, {"id": "Q6-39", "topic": "M2", "type": "single", "stem": "A separable SVM illustration includes many points far from the margin. Another valid point is added deep within its own class region. Which conclusion is most appropriate?", "options": ["The margin must shrink by exactly one unit", "Every new point must become a support vector", "The separator must rotate toward the densest class", "The margin-defining geometry need not change just because the sample count increased"]}, {"id": "Q6-40", "topic": "M4", "type": "single", "stem": "Two assigned two-dimensional observations are (2,8) and (6,4). Which candidate is their ordinary k-means center?", "options": ["(6,8)", "(2,4)", "(4,6)", "(8,12)"]}, {"id": "Q6-41", "topic": "M8", "type": "multi", "stem": "A regression of attendance on opening-hour duration uses data only for durations 6 to 10 hours. Its intercept predicts -20 visitors at zero hours. Which conclusions are appropriate?", "options": ["Zero duration is outside the fitted data range", "The intercept need not have a useful standalone operational interpretation", "The negative intercept alone proves every in-range prediction is invalid", "The intercept predicts attendance at the average observed duration"]}, {"id": "Q6-42", "topic": "M7", "type": "multi", "stem": "An ARIMA(3,0,0) candidate is proposed for an ordered visitor series. Which statements interpret this specification?", "options": ["No lagged-error moving-average terms are specified", "The zero middle entry specifies one differencing step", "Three seasonal factors are required by the first number", "Three prior modeled values enter the autoregressive part"]}, {"id": "Q6-43", "topic": "M2", "type": "single", "stem": "A document classifier returns genuine when f(x)>0 and forged otherwise. A document has f(x)=0. What does the stated rule return?", "options": ["Genuine, because equality always counts as positive", "Forged, because zero does not satisfy the positive condition", "A probability of exactly zero", "Both labels because a boundary has no usable rule"]}, {"id": "Q6-44", "topic": "M2", "type": "multi", "stem": "A collection has two interlocking class regions in a properly scaled feature plot. A linear SVM performs poorly. Which changes are plausible candidates rather than guaranteed cures?", "options": ["Try a kernel SVM for a nonlinear boundary", "A neighbor classifier can be judged solely by its training classifications", "Declare the response unsupervised because a line fails", "Investigate whether the chosen features adequately distinguish the classes"]}, {"id": "Q6-45", "topic": "M8", "type": "single", "stem": "A regression predicts 12 tickets for a case whose observed response is 17. An analyst measures the shortest geometric distance from the plotted point to the fitted line. What quantity belongs in ordinary response SSE?", "options": ["The difference in the predictor coordinate only", "The class probability at the point", "The squared response residual (17-12)^2=25", "The perpendicular distance regardless of response units"]}, {"id": "Q6-46", "topic": "M2", "type": "blank", "stem": "A feature has first been min-max scaled to u=.25. Converting u to the range [-2,2] using a+(b-a)*u gives ____.", "options": []}, {"id": "Q6-47", "topic": "M4", "type": "tf", "stem": "Assigning one new observation to its nearest stored k-means center necessarily updates all centers.", "options": []}, {"id": "Q6-48", "topic": "M7", "type": "blank", "stem": "A series has values 3,7,13. Its first differences are 4 and 6, so its second difference is ____.", "options": []}, {"id": "Q6-49", "topic": "M8", "type": "tf", "stem": "A normal-looking raw response histogram is enough by itself to establish every assumption of a regression.", "options": []}, {"id": "Q6-50", "topic": "M10", "type": "blank", "stem": "For specificity .92, the false-positive rate is ____.", "options": []}], [{"id": "Q7-01", "topic": "M6", "type": "single", "stem": "A monitor has baseline 50 and allowance 2. An analyst replaces the baseline with 52 and still subtracts allowance 2, believing this is unchanged. Which statement is correct?", "options": ["A baseline and allowance are always interchangeable labels", "The increment is unchanged because the allowance is named twice", "The positive increment is reduced by another 2; these written settings are not equivalent", "The threshold must become zero"]}, {"id": "Q7-02", "topic": "M8", "type": "single", "stem": "Two studies fit the same number of parameters, one using 30 observations and the other 3,000. Which statement best explains the purpose of the AICc correction?", "options": ["It replaces response labels with prior beliefs", "It gives the smaller study a guaranteed correct model", "It rewards larger parameter counts without considering sample size", "It addresses finite-sample model-size concerns more strongly in the smaller study"]}, {"id": "Q7-03", "topic": "M4", "type": "multi", "stem": "A reserve wants habitat clusters to reflect how often animals use locations and also to emphasize water access in similarity. Which statements distinguish the choices?", "options": ["A feature weight is the same as a learned response coefficient", "The two weighting choices serve different modeling roles", "Feature weights change what differences count as large", "Observation frequencies and feature weights are interchangeable settings"]}, {"id": "Q7-04", "topic": "M4", "type": "single", "stem": "Two habitat sites differ from a target by (water distance, elevation) of (2,0) and (0,3). Under squared distance 4*water_difference^2+elevation_difference^2, which is nearer?", "options": ["The second site, with objective distance 9 versus 16", "The first site, because 2 is less than 3 before weighting", "The comparison requires response labels", "Both, because one coordinate is zero at each"]}, {"id": "Q7-05", "topic": "M8", "type": "multi", "stem": "Two reports estimate the same slope 3. Their standard errors are .5 and 2. Under a zero-slope t-statistic, which statements are correct?", "options": ["The identical slope estimates imply identical uncertainty", "Standard error changes the evidence relative to zero without changing the reported point estimate", "The second t-statistic is 1.5", "The first t-statistic is 1.5 because both reports share the slope"]}, {"id": "Q7-06", "topic": "M3", "type": "multi", "stem": "Only 12 of 300 nests fail, and a random validation subset contains no failures. Which interpretations are correct?", "options": ["An evaluation with no failures estimates failure recall as zero", "The evaluation population needs cases relevant to the intended safety question", "Its overall accuracy cannot establish failure-detection performance", "Failure recall can be established as 100% from the absence of failures"]}, {"id": "Q7-07", "topic": "M4", "type": "single", "stem": "A team clusters nests using location and eventual success, then offers the resulting groups as purchase-time habitat segments for nests with unknown success. Which concern applies?", "options": ["The representation uses an attribute unavailable at assignment time", "K-means automatically predicts missing success with no separate assumptions", "Geographic distance cannot be used in clustering", "Known success must be included in every unsupervised fit"]}, {"id": "Q7-08", "topic": "M7", "type": "multi", "stem": "Weekly plant growth has a baseline increasing over time and a yearly oscillation of approximately fixed size in centimeters. Which statements are reasonable?", "options": ["A multiplicative seasonal factor is an amount in centimeters", "Single level-only smoothing explicitly contains both described components", "An additive seasonal representation matches a roughly fixed-size seasonal amount", "A trend component addresses the changing baseline"]}, {"id": "Q7-09", "topic": "M3", "type": "single", "stem": "A standardized classifier is evaluated after each validation observation is centered by its own value, making every centered feature zero. What went wrong?", "options": ["Validation must use learned training preparation, not case-specific recentering that erases differences", "Centering is impossible for supervised models", "The zero values prove the classifier has no informative predictors", "Every new observation should define its own training mean"]}, {"id": "Q7-10", "topic": "M6", "type": "multi", "stem": "The same four observations are analyzed in two different orders using a reset-to-zero CUSUM. Which statements are warranted?", "options": ["Shuffling is innocuous when the task is to detect the timing of a change", "Resetting means ordered paths matter beyond the unordered total", "CUSUM is always a function only of the sample mean", "The sequence of statistics and alarms can differ"]}, {"id": "Q7-11", "topic": "M3", "type": "single", "stem": "A fixed non-test dataset has 600 nests. Under equally sized three-fold and six-fold CV, what distinguishes each individual fitting run?", "options": ["Three-fold fits use 200; six-fold fits use 100", "Three-fold fits use 400 nests; six-fold fits use 500", "Both fit all 600 before every validation prediction", "Fold count changes the number of nest-success classes"]}, {"id": "Q7-12", "topic": "M6", "type": "single", "stem": "Detector A generates two false alarms and detects a shift quickly. B generates none but leaves a harmful shift undetected much longer. Which information is needed to prefer one?", "options": ["The identity of the detector with fewer alarms alone", "Only whether every statistic is positive", "Only the number of fitted regression slopes", "The consequences of false alarms and delayed detection"]}, {"id": "Q7-13", "topic": "M2", "type": "single", "stem": "A classifier predicts occupied when 3*rainfall+temperature-12>0. Rainfall rises by 1 while temperature falls by 3. What happens to the score?", "options": ["It is unchanged, because the two score changes cancel", "It becomes a probability of zero", "It necessarily rises because rainfall rises", "It flips sign for every starting observation"]}, {"id": "Q7-14", "topic": "M9", "type": "single", "stem": "Two standardized habitat predictors have essentially no correlation and the same variance. PCA reports two equal eigenvalues. Which conclusion is reasonable?", "options": ["The outcome has equal dependence on both predictors", "There is no uniquely more important variance direction from the eigenvalue ranking alone", "Equal eigenvalues prove identical predictor columns", "The second direction necessarily carries no information"]}, {"id": "Q7-15", "topic": "M7", "type": "multi", "stem": "A river-height series is differenced once before modeling. The predicted next difference is -2 cm and the latest observed height is 15 cm. Which statements are correct?", "options": ["A level prediction of 13 cm follows by adding the difference to the latest height", "The modeled target has changed from a level to an increment", "A negative difference forces a negative height", "The predicted difference should be used as the next height without reconstruction"]}, {"id": "Q7-16", "topic": "M7", "type": "single", "stem": "A GARCH analysis of centimeter-valued river-height forecast errors reports variance 9. Which interpretation of the units is correct?", "options": ["The response height must be zero whenever variance is positive", "Variance is a unitless class probability", "Variance is automatically a height of 9 cm", "Variance is in squared centimeters; it is not a 9 cm level forecast"]}, {"id": "Q7-17", "topic": "M7", "type": "single", "stem": "A Holt fit to one observation per quarter estimates trend 6 seedlings per observation. What does its ordinary two-step trend contribution represent?", "options": ["12 seedlings over two quarters", "6 seedlings because trend is not horizon-dependent", "A seasonal probability of .12", "12 seedlings over two days regardless of indexing"]}, {"id": "Q7-18", "topic": "M7", "type": "multi", "stem": "Two level smoothers start at 40. Their next observation is 70; A uses alpha=0 and B uses alpha=1. Which statements are correct?", "options": ["B becomes 70", "A must average 40 and 70 because smoothing always does", "These endpoint choices give radically different responsiveness", "A becomes 55 because alpha=0 gives equal old and new weight"]}, {"id": "Q7-19", "topic": "M8", "type": "single", "stem": "Overall, shaded plots have taller plants. In a regression adjusting for species, the shade coefficient is negative. Which interpretation is defensible?", "options": ["Adjustment makes the shade coefficient unrelated to the included species", "At least one result must be a calculation error", "The adjusted comparison and the overall comparison need not have the same sign", "The negative coefficient proves shade causally harms every plant"]}, {"id": "Q7-20", "topic": "M10", "type": "single", "stem": "A spline growth model joins polynomial pieces at selected sunlight values. What do those selected values represent?", "options": ["The response variance predicted by GARCH", "Class labels for occupied and unoccupied plots", "Knots where pieces join", "The error-lag count in ARIMA"]}, {"id": "Q7-21", "topic": "M5", "type": "single", "stem": "A tree-height file mostly uses meters, but one verified height was entered in centimeters. Which handling is most justified?", "options": ["Interpret the raw numeric rank as biological importance", "Treat it as an exceptionally tall tree without checking units", "Convert the verified record to the agreed units and preserve the actual measurement", "Remove all tall trees to make the histogram normal"]}, {"id": "Q7-22", "topic": "M4", "type": "single", "stem": "WSS falls sharply until k=3 and then more slowly, but another analyst sees a weaker elbow at k=4. Which interpretation is most appropriate?", "options": ["Elbow interpretation can be judgmental; use the operational purpose and feasibility as well", "An elbow uniquely proves the true number of ecological species", "The last tested k is always optimal", "A visually ambiguous elbow invalidates every cluster assignment"]}, {"id": "Q7-23", "topic": "M3", "type": "single", "stem": "A park compares classifiers using accuracy but will deploy the one minimizing expensive missed invasive-species cases. Which issue should be addressed?", "options": ["Replace validation by training accuracy because costs are operational", "Infer that every false positive has zero consequence", "Choose the highest accuracy and assign costs afterward without reconsidering", "Use a validation criterion reflecting the stated missed-case consequences"]}, {"id": "Q7-24", "topic": "M2", "type": "multi", "stem": "A wildlife table has one row per nest and columns for species, elevation, and success status. Which statements correctly describe its structure?", "options": ["Elevation is a quantitative feature", "Success can be the response for a supervised success classifier", "Rows are necessarily the predictors and columns the nests", "Species is categorical even if represented by a numeric code"]}, {"id": "Q7-25", "topic": "M8", "type": "multi", "stem": "Which proposed growth equations are linear in their unknown coefficients?", "options": ["y=b0+exp(b1*x)", "y=b0+b1*log(x), with x positive", "y=b0+b1*x*z", "y=b0+b1*x+b2*x^2"]}, {"id": "Q7-26", "topic": "M10", "type": "multi", "stem": "A Bayesian regression combines strong prior expectations about growth with a small field dataset suggesting a different effect. Which statements fit the introductory survey?", "options": ["Observed data is ignored by definition", "Prior information can influence the result when observations are limited", "Prior beliefs are uncertainty distributions rather than known response labels", "The prior and its suitability should be examined"]}, {"id": "Q7-27", "topic": "M1", "type": "multi", "stem": "A conservation team asks for next-month total nesting pairs, each nest's success category, and a patrol route under a mileage limit. Which statements distinguish the tasks?", "options": ["The route constraint turns the nesting count into a class label", "The constrained route is an action-selection task", "All three require the same response encoding", "The total is a numeric predictive target"]}, {"id": "Q7-28", "topic": "M3", "type": "multi", "stem": "A selected rainfall regression is refit on all non-test data, producing slopes different from every CV fold. Which statements are justified?", "options": ["Different final slopes alone mean the CV procedure failed", "CV selects the specification rather than one fold's exact coefficients", "The untouched test can assess the final refitted procedure", "Different fitted samples can give different slopes"]}, {"id": "Q7-29", "topic": "M2", "type": "single", "stem": "A 5-NN nest classifier predicts five new unlabeled nests. One analyst uses the other four new nests as labeled neighbors even though their outcomes are unknown. What is the correction?", "options": ["The five new nests make the model five-fold cross-validation", "New cases must be discarded because k-NN cannot predict batches", "The vote needs neighbors with known training responses", "Unlabeled proximity automatically supplies success labels"]}, {"id": "Q7-30", "topic": "M1", "type": "single", "stem": "Rainfall predicts bird counts accurately, so a park manager proposes spraying water to increase the population. Which missing distinction matters most?", "options": ["Predicting counts from rainfall does not establish the effect of an artificial intervention", "Rainfall cannot be used for prediction unless experimentally controlled", "Prediction is impossible when an input is associated with the response", "A predictor with low error must be a manipulable cause"]}, {"id": "Q7-31", "topic": "M2", "type": "multi", "stem": "Every training observation has the same sensor-calibration value. A standardizer attempts (x-mean)/standard deviation. Which statements are appropriate?", "options": ["The field has no variation in the training sample", "A constant field should be considered during feature preparation", "Assigning an arbitrary tiny denominator creates learned signal", "The zero denominator requires an explicit handling policy"]}, {"id": "Q7-32", "topic": "M5", "type": "multi", "stem": "A rare nest failure has completely ordinary elevation and rainfall values. Which statements are correct?", "options": ["An unusual response need not be an extreme point in every predictor", "A suitable response model may help assess its conditional unusualness", "Ordinary feature values make the rare response impossible", "The record must be fraudulent because its inputs look ordinary"]}, {"id": "Q7-33", "topic": "M10", "type": "single", "stem": "Two candidate regression-tree splits have total child SSE values 30 and 45 on the same parent cases. Under the stated minimum-SSE split objective, which is preferred?", "options": ["Neither can be compared without class probabilities", "The split with total SSE 30", "The split with total SSE 45 because larger is better", "Whichever has the smallest child regardless of total SSE"]}, {"id": "Q7-34", "topic": "M7", "type": "single", "stem": "A forecaster describes ARIMA(0,0,2) as the average of the last two river-height readings. Which correction is appropriate?", "options": ["It uses two levels and one difference", "Its first zero means there is no numeric response", "It requires two clusters of river sites", "Its MA part uses two lagged prediction errors, not a rolling average of two raw readings"]}, {"id": "Q7-35", "topic": "M1", "type": "single", "stem": "A wildlife report describes (i) regression, (ii) regression on rainfall and vegetation, and (iii) a fitted intercept and two slopes. Which statement connects these descriptions?", "options": ["The predictors alone uniquely determine the fitted coefficients", "All three are unsupervised cluster labels", "They are respectively a family, a specification, and a fitted numerical instance", "Only the third description can ever be called a model in the course"]}, {"id": "Q7-36", "topic": "M2", "type": "single", "stem": "A fitted linear rule is 2*x+z>10. An analyst replaces x by u=x/100. Which equivalent rule preserves all decisions?", "options": ["2*u+100*z>10", "u+z>1000", "2*u+z>10", "200*u+z>10"]}, {"id": "Q7-37", "topic": "M9", "type": "multi", "stem": "A positive response is transformed using one fitted Box-Cox power. Which statements are correct?", "options": ["Choosing a power is the same operation as choosing the number of clusters", "The transformation operates on numeric response values", "Different powers represent different response-scale transformations", "The selected transformation still needs model checks"]}, {"id": "Q7-38", "topic": "M8", "type": "multi", "stem": "A growth model is y=10+2*water+3*shade+4*water*shade, with shade coded 0 or 1. Which statements interpret the water slope?", "options": ["It is 2 for shade=0", "It is 2 for shade=1 because the interaction never affects slopes", "The interaction allows the water effect to depend on shade", "The coefficient 2 alone applies to both groups"]}, {"id": "Q7-39", "topic": "M6", "type": "single", "stem": "After every high reading, an analyst immediately increases the reference baseline to that reading, then reports that no persistent increase exists. What is the strongest concern?", "options": ["CUSUM cannot use any chosen baseline", "Higher readings necessarily imply lower variance", "Updating any reference automatically proves no process change", "The changing reference may track away the very departure the monitor was meant to detect"]}, {"id": "Q7-40", "topic": "M10", "type": "multi", "stem": "In 1,000 evaluated plots, 980 truly lack an invasive species. A rule always declares absence. Which statements are correct?", "options": ["Its sensitivity to the 20 actual positive plots is zero", "Its false-positive count is zero", "Its accuracy is .98", "High accuracy alone establishes useful invasive-species detection"]}, {"id": "Q7-41", "topic": "M5", "type": "single", "stem": "An analyst removes all difficult storm observations from the evaluation set, then advertises all-weather performance. What is the main problem?", "options": ["Evaluation never needs to include rare weather", "Deleting test errors improves the model itself", "The evaluated population no longer supports the claimed all-weather target", "All difficult observations are invalid by definition"]}, {"id": "Q7-42", "topic": "M2", "type": "multi", "stem": "For one nest, 1-NN is correct while 9-NN is wrong. Which conclusions follow?", "options": ["Validation across representative cases should guide k", "Increasing k is not a guarantee of improvement on every case", "Larger k necessarily uses more local examples than smaller k", "One case determines the best k for the entire population"]}, {"id": "Q7-43", "topic": "M4", "type": "multi", "stem": "A k=4 run reports WSS=120, while a k=3 run reports 100 on the same prepared data. Which statements are defensible?", "options": ["The discrepancy proves the k=3 global optimum is 100", "The two reported heuristic results do not establish the relationship between global optima", "The globally best k=4 objective must exceed the globally best k=3 objective", "The k=4 run may have stopped at a worse local solution"]}, {"id": "Q7-44", "topic": "M9", "type": "multi", "stem": "Six original soil measurements are replaced by two PCA scores. Which statements distinguish the representation?", "options": ["The first score must be the soil variable with the largest original mean", "The transformation is feature extraction", "Two scores do not mean that four raw columns were merely deleted", "Each score is necessarily one unchanged original measurement"]}, {"id": "Q7-45", "topic": "M10", "type": "single", "stem": "A 200-case parent node proposes children of sizes 8 and 192. A rule requires every child to have at least 10 cases. Which statement follows?", "options": ["It is allowed because the average child size is 100", "This split violates the stated child-size rule", "The rule requires exactly 10 cases in every leaf", "It is allowed because the parent has more than 10 cases"]}, {"id": "Q7-46", "topic": "M3", "type": "blank", "stem": "In equally sized four-fold CV, each observation is used for training ____ times.", "options": []}, {"id": "Q7-47", "topic": "M5", "type": "tf", "stem": "A measurement can be an outlier in one appropriate context and ordinary in another.", "options": []}, {"id": "Q7-48", "topic": "M6", "type": "blank", "stem": "A lower monitor starts at zero with mu=12 and C=1, using S_new=max(0,S+mu-x-C). Readings 14 then 8 leave final statistic ____.", "options": []}, {"id": "Q7-49", "topic": "M9", "type": "tf", "stem": "Ordinary PCA uses response labels to choose the highest-variance component.", "options": []}, {"id": "Q7-50", "topic": "M10", "type": "blank", "stem": "The regression family introduced for an attribute-dependent expected count or arrival rate is ____ regression.", "options": []}], [{"id": "Q8-01", "topic": "M1", "type": "multi", "stem": "A music academy must explain scholarship decisions using understandable factors. A complex model has slightly better validation accuracy than a transparent one. Which statements are appropriate?", "options": ["Interpretability guarantees the transparent model is more accurate", "Compare the performance tradeoff against the actual decision requirements", "The small score gain does not settle the operational choice alone", "Explanation requirements can be ignored once a model wins validation"]}, {"id": "Q8-02", "topic": "M3", "type": "multi", "stem": "A large validation dataset contains only one advanced course, while deployment covers introductory and advanced courses. Which statements follow?", "options": ["Large sample size alone does not ensure relevant course coverage", "A million rows eliminates the need to inspect population differences", "The score mainly supports performance on the represented conditions", "Additional appropriate evaluation conditions may be needed"]}, {"id": "Q8-03", "topic": "M9", "type": "multi", "stem": "Subtracting a fitted linear trend from attendance leaves a repeating weekly pattern. Which statements are justified?", "options": ["The trend removal did not remove the seasonal structure", "A model for the remainder may still need time structure", "Successful subtraction establishes independent identical errors automatically", "The residual pattern can guide further specification"]}, {"id": "Q8-04", "topic": "M3", "type": "single", "stem": "A student-performance model has large errors in both training and validation, and residuals show an obvious omitted curved pattern. Which next step is most supported?", "options": ["Choose a final test threshold until training error vanishes", "Consider a representation or model flexible enough to capture the missing pattern", "Reduce flexibility solely because every large error implies overfitting", "Delete all observations on the curve"]}, {"id": "Q8-05", "topic": "M5", "type": "single", "stem": "A small class has one student with an exceptionally low final mark after a verified extended absence. Which question is most important before excluding the record?", "options": ["Whether such students belong to the intended prediction population", "Whether its record appears last in the file", "Whether a more attractive plot results", "Whether deleting it raises training R-squared"]}, {"id": "Q8-06", "topic": "M7", "type": "multi", "stem": "A level smoother starts at 20 with alpha=.5, then sees 30 and 10. Which statements are correct?", "options": ["The successive levels are 25 and 20 because recursion equally weights all history", "The final level is simply the average of all three values", "The latest low observation has more direct weight than the earlier high one", "The earlier high observation still contributes through the previous level"]}, {"id": "Q8-07", "topic": "M2", "type": "single", "stem": "A linear class rule assigns positive when f(x)>0. Another report uses -f(x)>0 but keeps the same positive class name. Which interpretation is correct?", "options": ["Only zero scores are affected", "Negating a classifier score never changes class assignments", "The new score is the old probability complement automatically", "Away from the boundary, the class assignments are reversed"]}, {"id": "Q8-08", "topic": "M10", "type": "single", "stem": "A tree leaf fits a local regression y=20+3*x instead of a constant mean. At x=4, which distinction applies?", "options": ["It predicts 32 under a model-tree leaf rather than returning one constant for all leaf cases", "It is a classification vote because the tree has branches", "It must predict the training leaf mean regardless of the local equation", "It requires one separate tree per coefficient"]}, {"id": "Q8-09", "topic": "M5", "type": "multi", "stem": "An audio metronome sequence omits one expected click. None of the recorded click intensities is extreme. Which statements are correct?", "options": ["A missing event can never be modeled because it has no amplitude", "Click intensity alone necessarily detects the missing click", "Inter-click duration can expose the gap as an unusually long interval", "Representation can change how an anomaly appears"]}, {"id": "Q8-10", "topic": "M6", "type": "single", "stem": "An academy wants both a predicted mark for each student from attributes and an alarm when cohort attendance shifts persistently. Which pairing is most direct?", "options": ["k-means as the numeric mark predictor; CV as the alarm", "CUSUM for every student mark; PCA as the shift alarm", "GARCH as a deterministic attendance-class label", "Regression for marks; CUSUM for the ordered attendance shift"]}, {"id": "Q8-11", "topic": "M8", "type": "multi", "stem": "A marks regression has fitted response 50+2*hours. A student moves from 4 to 7 practice hours, with other included inputs fixed. Which statements follow?", "options": ["The fitted difference is 6 marks", "The difference is 56 because the intercept must be added to the change", "The statement describes the fitted relationship, not a guaranteed individual intervention effect", "The two predictions are 58 and 64"]}, {"id": "Q8-12", "topic": "M8", "type": "single", "stem": "A predictive marks model has one predictor with a wide coefficient interval but improves representative held-out error when kept. Which conclusion is most appropriate?", "options": ["Declare it causal because error improved", "Do not decide predictive value from the coefficient test alone; assess the complete prediction procedure", "Replace held-out performance by the smallest p-value", "Delete it automatically because only significant coefficients can predict"]}, {"id": "Q8-13", "topic": "M9", "type": "multi", "stem": "PCA eigenvalues are 6,3,1. Which statements about retaining the first two directions are correct?", "options": ["The response prediction must explain 90% of marks", "The retained variance summary is not itself supervised predictive accuracy", "The discarded direction has 10% of that variance", "They retain 90% of prepared predictor variance"]}, {"id": "Q8-14", "topic": "M2", "type": "single", "stem": "For k=3, the first two examples are uniquely nearest, but three more tie for the third distance and have different labels. Which issue must be specified?", "options": ["Whether k=3 means three output classes", "Whether every class has a numeric mean", "Whether the classifier is actually unsupervised", "How the tied boundary neighbors are selected or handled"]}, {"id": "Q8-15", "topic": "M3", "type": "multi", "stem": "One random split gives a poor validation result; an analyst repeats splits until finding a flattering score and reports only that one. Which concerns are warranted?", "options": ["Split variation should be represented honestly", "The reported score is selected for favorable variability", "The chosen split is guaranteed most representative", "Changing random seeds creates new independent deployment evidence without qualification"]}, {"id": "Q8-16", "topic": "M10", "type": "single", "stem": "A classifier originally labels dropout as positive. A report relabels completion as positive without changing predictions or cases. Which statement is correct?", "options": ["Accuracy must fall solely because positive was renamed", "Old true negatives become new true positives, and old false positives become new false negatives", "Precision must equal its old value under every class reversal", "Every cell count keeps the same name"]}, {"id": "Q8-17", "topic": "M4", "type": "single", "stem": "Two Euclidean centers are (0,0) and (4,0). Which statement describes their equal-distance boundary?", "options": ["A class label learned from responses", "The full disk around the first center", "The vertical line x=2", "The horizontal line y=2"]}, {"id": "Q8-18", "topic": "M7", "type": "single", "stem": "A campus records attendance every half hour and studies a repeating 24-hour pattern. What is the seasonal period in observations?", "options": ["48", "24", "12", "30"]}, {"id": "Q8-19", "topic": "M6", "type": "single", "stem": "A study says school engagement periods became longer because their detected end dates moved later. Which missing information matters?", "options": ["Whether one can rename the final CUSUM value", "Whether the detected start dates also changed", "Whether all period-end values are positive", "Whether k-NN used odd k"]}, {"id": "Q8-20", "topic": "M3", "type": "single", "stem": "A tutor predicts a student's next assessment after three completed lessons. Historical predictors include later final-course grades. Which statement best identifies the issue?", "options": ["A chronological row sort automatically makes the later grades timely", "All grades are valid predictors because the rows are historical", "Using a forest removes the timing problem", "Later grades are unavailable at the three-lesson prediction point"]}, {"id": "Q8-21", "topic": "M4", "type": "multi", "stem": "An audio workflow uses k-means with k=4, 7-NN classification, and five-fold CV. Which statements interpret the numbers?", "options": ["Seven is the neighborhood size for voting", "Five is the number of validation folds", "Four is the number of cluster centers", "All three specify the number of predicted music genres"]}, {"id": "Q8-22", "topic": "M10", "type": "single", "stem": "For a numeric performance target, five tree predictions are 40,45,50,55,60. Under simple forest averaging, what is predicted?", "options": ["250", "50", "The most frequent class, which is undefined here", "60 because the highest tree dominates"]}, {"id": "Q8-23", "topic": "M1", "type": "multi", "stem": "An education team says it will use trees, but has not decided between predicting exam marks and completion categories. Which statements are justified?", "options": ["The operational request should settle what is to be predicted", "Using trees makes both targets identical", "The response type affects whether the tree is regression or classification", "The family name does not supply the target or fitted rules"]}, {"id": "Q8-24", "topic": "M2", "type": "multi", "stem": "A tutor needs a pass/fail prediction from labeled student records, not a fitted probability. Which statements are defensible?", "options": ["A classification tree is a candidate", "k-NN voting is another candidate", "A classification SVM is a candidate", "Only logistic regression can ever return a class"]}, {"id": "Q8-25", "topic": "M7", "type": "multi", "stem": "An audio-level mean forecast is close to zero, but its GARCH variance forecast is high. Which statements are defensible?", "options": ["High variance proves the next signed level is positive", "The variance forecast serves a different output than the mean forecast", "Risk planning may need both outputs", "Near-zero expected level does not imply small fluctuations"]}, {"id": "Q8-26", "topic": "M7", "type": "single", "stem": "A multiplicative seasonal forecast has current level 100, one-step trend 10, and next seasonal factor .8. Which statement is correct?", "options": ["The seasonal factor adds .8 units to 110", "The factor .8 means an 80% chance the response is positive", "The forecast must exceed 100 because trend is positive", "The forecast is 88, so a positive trend can coexist with a next forecast below the current level"]}, {"id": "Q8-27", "topic": "M7", "type": "single", "stem": "An academy has a short series of eight term totals and wants a complex lag model. What is the best high-level modeling response?", "options": ["Treat the lecture observation guideline as proof no forecast can be made", "Assume more lag parameters always help because ARIMA is general", "Assess whether the data supports the complexity and compare simpler candidates", "Duplicate each observation to create independent evidence"]}, {"id": "Q8-28", "topic": "M8", "type": "single", "stem": "Two models have the same likelihood improvement for an additional parameter. Under AIC penalty 2*K and BIC penalty K*log(n), which statement is correct for increasing n?", "options": ["The BIC extra-parameter penalty grows with log(n), while the AIC penalty per parameter stays 2", "BIC always rewards the extra parameter more as n grows", "AIC becomes identical to training SSE for every n", "Both penalties are determined only by the response units"]}, {"id": "Q8-29", "topic": "M2", "type": "multi", "stem": "Two acoustic features each have training mean zero, but standard deviations 1 and 100. Which statements about standardization are correct?", "options": ["The feature with SD 100 must be more predictive", "Each standardized value expresses departure in its training SD units", "Equal feature means make their unscaled variabilities equal", "Dividing by the respective standard deviations gives comparable standardized units"]}, {"id": "Q8-30", "topic": "M7", "type": "multi", "stem": "The lecture calls ARIMA(0,1,0) a random walk. Which statements interpret the specification at the course level?", "options": ["The name means every level must move upward", "It has no value-lag or error-lag terms in the differenced model", "It has one differencing step", "It is a time-series specification, not a cluster assignment"]}, {"id": "Q8-31", "topic": "M2", "type": "single", "stem": "An audio classifier receives raw rehearsal recordings rather than a numeric feature table. Which statement best describes a preparation need?", "options": ["Use the byte count as the class without defining a target", "Create a suitable representation of the recording for the intended classifier", "Treat each entire recording filename as a meaningful Euclidean coordinate", "Assume all unstructured recordings have no response labels"]}, {"id": "Q8-32", "topic": "M4", "type": "single", "stem": "An academy clusters practice-room usage by one row per booked hour rather than one row per student. Which statement is most appropriate?", "options": ["The grouping now emphasizes usage frequency rather than equal student weight", "Hours become categorical class labels automatically", "The model has become regression because rows increased", "The two datasets must produce identical centers"]}, {"id": "Q8-33", "topic": "M9", "type": "single", "stem": "A PCA result contains one table of feature weights and another with one row per recording. Which statement best distinguishes them?", "options": ["Feature weights are loadings; per-recording projected coordinates are scores", "Both tables must contain response probabilities", "Loadings require one row per outcome label", "Scores are the variances of original predictors"]}, {"id": "Q8-34", "topic": "M2", "type": "multi", "stem": "A new song is classified using the labels of the closest training recordings. Which statements describe a neighbor method?", "options": ["The definition of acoustic distance matters", "It requires one fixed straight-line class separator", "Stored labeled examples can determine a local vote", "Changing k changes which neighborhood informs the answer"]}, {"id": "Q8-35", "topic": "M6", "type": "single", "stem": "A CUSUM statistic reaches 12 against a threshold of 10. A tutor says the attendance mean increased exactly 12 percentage points. What is the best correction?", "options": ["The statistic is a regression coefficient with units of causal effect", "Any crossing gives an exact future attendance forecast", "The statistic is accumulated evidence, not automatically the magnitude of the mean shift", "The threshold specifies the new attendance mean"]}, {"id": "Q8-36", "topic": "M4", "type": "multi", "stem": "Song clusters have stable mean tempos across several starts. A report says tempo caused every genre label. Which conclusions are appropriate?", "options": ["Repeated starts turn an unsupervised fit into an experiment", "The stability can be useful without proving causality", "Stable clusters must equal the true musical genre labels", "Stable clustering geometry does not establish a causal mechanism"]}, {"id": "Q8-37", "topic": "M3", "type": "multi", "stem": "An analyst compares raw features, standardized features, and PCA features, then selects the best validation score. Which statements are correct?", "options": ["The representation choice is part of the selected procedure", "Only the final classifier family counts as a tuned choice", "An untouched test should assess the chosen complete pipeline", "Calling preprocessing unsupervised removes all evaluation responsibilities"]}, {"id": "Q8-38", "topic": "M10", "type": "single", "stem": "Two completion models rank every pair of students identically but give different numerical probability estimates. Which statement is most defensible?", "options": ["Identical ranking guarantees every probability is accurate", "Their AUC can match even though their probabilities and threshold decisions differ", "AUC alone chooses the correct tutoring budget", "Their AUC must differ because each probability changed"]}, {"id": "Q8-39", "topic": "M8", "type": "multi", "stem": "A report labels likelihood as the probability that the fitted coefficient is true, given the observations. Which correction is justified?", "options": ["Continuous outcomes may involve densities rather than exact-point probabilities", "Likelihood varies parameters while evaluating the observed data under the assumed model", "Likelihood alone is not a posterior probability of a coefficient", "Maximum likelihood requires that every observation be the most likely possible value"]}, {"id": "Q8-40", "topic": "M10", "type": "multi", "stem": "A tutoring policy assigns support to predicted at-risk students. Each assigned session costs $4 even if the student is truly at risk. Which statements are correct?", "options": ["Correct classifications must always have zero operational cost", "True-positive actions can carry costs as well as false-positive actions", "A full value calculation can include all four confusion cells", "Counting only errors may omit real resource use"]}, {"id": "Q8-41", "topic": "M5", "type": "single", "stem": "A database contains ten copies of one student record due to an import failure and one valid extraordinary performance. Which handling best fits the evidence?", "options": ["Keep the duplication because repeated rows are always meaningful", "Correct the verified duplication separately from judging the genuine unusual result", "Delete both because all unusual rows have the same status", "Replace both records with the overall response mean automatically"]}, {"id": "Q8-42", "topic": "M6", "type": "multi", "stem": "An upper CUSUM starts at zero with baseline 10 and allowance 2. Every observation equals 11. Under S_new=max(0,S+x-mu-C), which statements are correct?", "options": ["The statistic stays zero", "The settings determine which departures accumulate", "Any persistent above-baseline value necessarily triggers this monitor eventually", "The +1 departure is smaller than the allowance"]}, {"id": "Q8-43", "topic": "M8", "type": "single", "stem": "On one fitted dataset, response SST is 100 and residual SSE is 30. Which interpretation of ordinary R-squared is correct?", "options": ["R-squared is .3 because SSE is the numerator", "R-squared is .7 relative to the mean-response baseline", "Seventy percent of students must be classified correctly", "Every prediction error is 30 marks"]}, {"id": "Q8-44", "topic": "M4", "type": "multi", "stem": "A clustering analyst evaluates k using an elbow on WSS, but discovers an acoustic feature was recorded 1,000 times larger than intended. Which statements are warranted?", "options": ["An elbow is conditional on the chosen prepared geometry", "Selecting k automatically repairs feature-unit mistakes", "Correct the representation before trusting its elbow for the intended problem", "An elbow removes the effect of incorrectly scaled coordinates"]}, {"id": "Q8-45", "topic": "M1", "type": "single", "stem": "A dashboard groups students by study habits and displays each group's current attendance. Which additional step is needed before claiming it identifies the best attendance intervention?", "options": ["Simply renaming every group an intervention", "Evidence about how feasible actions affect the objective", "Computing the same descriptive averages twice", "Choosing the cluster with the largest numeric identifier"]}, {"id": "Q8-46", "topic": "M1", "type": "tf", "stem": "Selecting the regression family also uniquely fixes which predictors must be included.", "options": []}, {"id": "Q8-47", "topic": "M2", "type": "blank", "stem": "A scaler learned minimum 10 and maximum 30. A stored min-max value .25 corresponds to original value ____.", "options": []}, {"id": "Q8-48", "topic": "M6", "type": "blank", "stem": "In an upper CUSUM, three positive raw increments of 2 with no resets produce statistic ____ from initial zero.", "options": []}, {"id": "Q8-49", "topic": "M7", "type": "tf", "stem": "A quarterly series' ordinary four-step forecast refers to one year ahead.", "options": []}, {"id": "Q8-50", "topic": "M8", "type": "blank", "stem": "For estimated coefficient -6 and standard error 2, the zero-null t-statistic is ____.", "options": []}], [{"id": "Q9-01", "topic": "M2", "type": "single", "stem": "A table includes route ID, travel minutes, and late status. Which statement about the response is most appropriate?", "options": ["Travel minutes or late status can be the response depending on the stated task", "The route ID must always be the numeric response", "Every table has one permanent response independent of the task", "Only the leftmost column can be a response"]}, {"id": "Q9-02", "topic": "M3", "type": "single", "stem": "Historical trips include repeated routes and dates. Deployment might be future trips on current routes or trips on entirely new routes. Which clarification most affects evaluation design?", "options": ["Whether the CSV filename contains spaces", "Whether the model uses exactly ten parameters", "Whether the target includes unseen routes or only future dates on existing routes", "Whether all route identifiers are odd numbers"]}, {"id": "Q9-03", "topic": "M2", "type": "multi", "stem": "The first three neighbors vote late,late,on-time. The next four all vote on-time. Which statements compare 3-NN and 7-NN?", "options": ["A larger neighborhood can reverse a local prediction", "7-NN returns on-time", "Increasing k always preserves the original class", "3-NN returns late"]}, {"id": "Q9-04", "topic": "M5", "type": "multi", "stem": "A travel-time sensor reports -8 minutes, and source logs confirm a sign corruption. A different trip genuinely takes 180 minutes during flooding. Which statements are appropriate?", "options": ["A negative recorded duration should be investigated rather than treated as ordinary elapsed time", "Treat the true flood delay according to target relevance", "Correct the verified corruption if possible", "Both must be deleted for the same reason"]}, {"id": "Q9-05", "topic": "M3", "type": "multi", "stem": "A transport team chooses the entire pipeline using only non-test data, freezes it, and evaluates once on a representative test set. Which statements are correct?", "options": ["The test result can be reported with its target population and limitations", "The estimate still has finite-sample uncertainty", "The test assesses the selected procedure rather than chooses it", "A single test score guarantees future performance in every weather regime"]}, {"id": "Q9-06", "topic": "M6", "type": "multi", "stem": "A team wants to detect both increased and decreased average journey time. Which statements describe a two-sided setup?", "options": ["Use appropriately defined upper and lower directional statistics", "The lower monitor can serve a different directional objective", "Keep the sign and threshold convention internally consistent", "An upper monitor alone necessarily detects every decrease"]}, {"id": "Q9-07", "topic": "M2", "type": "single", "stem": "A route classifier has extreme unit imbalance across distance coordinates. An analyst says soft-margin tuning makes preparation irrelevant. Which response is appropriate?", "options": ["A soft margin forces all features to have equal training SD", "Preparation is only for unsupervised models", "The penalty guarantees the representation captures useful information", "Penalty tuning and feature representation are different choices; both can affect the fitted classifier"]}, {"id": "Q9-08", "topic": "M4", "type": "multi", "stem": "Rush-hour trips and overnight trips have different geographic patterns. Which statements justify time-specific clustering?", "options": ["Splitting by time proves temporal differences cause every delay", "Separate analyses can represent different service contexts", "The eventual service plan should still consider resources and constraints", "Their center sets need not coincide"]}, {"id": "Q9-09", "topic": "M6", "type": "single", "stem": "A monitor resets its statistic to zero before every update and claims to detect runs of small positive delay departures. What is lost?", "options": ["Evidence no longer accumulates across observations", "Every observation becomes a regression coefficient", "The threshold becomes an event probability", "The allowance changes into seasonal cycle length"]}, {"id": "Q9-10", "topic": "M10", "type": "single", "stem": "A forest randomly limits candidate predictors. A report claims the trees' prediction errors are therefore mathematically independent. Which response is best?", "options": ["Random predictor selection ensures zero correlation by definition", "The forest cannot share training cases under any setup", "The restriction encourages diversity but does not establish independent errors", "Every tree now predicts an unrelated response"]}, {"id": "Q9-11", "topic": "M10", "type": "single", "stem": "A breakdown model has TN=80, FN=20, TP=10, FP=10. Dispatch asks what fraction of negative predictions truly have no breakdown. Which statement is correct?", "options": ["Negative predictive value is 80/(80+20)=.8", "Accuracy is always the same as this conditional fraction", "False positives belong in the negative-prediction denominator", "Specificity is the requested fraction 80/(80+10)"]}, {"id": "Q9-12", "topic": "M9", "type": "multi", "stem": "One analyst tunes Box-Cox lambda, another tunes smoothing alpha. Which statements are correct?", "options": ["Lambda chooses a response transformation in the stated family", "Both symbols necessarily have the same operational effect", "Alpha controls the new-observation weight in the smoother", "Parameter meanings depend on the model definition"]}, {"id": "Q9-13", "topic": "M7", "type": "single", "stem": "Using C_new=gamma*(x/S_new)+(1-gamma)*C_old, x=120, S_new=100, C_old=1, gamma=.5 gives which seasonal factor?", "options": [".6", "1.1", "110", "1.6"]}, {"id": "Q9-14", "topic": "M4", "type": "single", "stem": "A route clustering uses only start/end coordinates. The team adds time of day with a meaningful representation and weight. Which statement is most appropriate?", "options": ["The added dimension only changes the names of centers", "It now defines similarity in a richer space and can change groups even with the same k", "Cluster memberships must remain identical because locations are unchanged", "The new coordinate becomes a response label"]}, {"id": "Q9-15", "topic": "M3", "type": "single", "stem": "Model A is ranked using mean absolute delay error, while B is ranked using mean squared error on the same trips. Which statement is justified?", "options": ["Choose a common relevant metric before declaring one better from incomparable scores", "The two raw scores can be compared numerically regardless of units", "MSE always equals absolute error when the response is numeric", "A lower number under either metric guarantees lower cost"]}, {"id": "Q9-16", "topic": "M8", "type": "multi", "stem": "Two travel-time models make errors (0,10) and (5,5). Which statements under total SSE are correct?", "options": ["They have equal SSE because both absolute-error totals are 10", "The first SSE is 100", "Squaring puts a stronger penalty on the single large error", "The second SSE is 50"]}, {"id": "Q9-17", "topic": "M2", "type": "multi", "stem": "A distance-based model codes a two-category vehicle type as 0/1. Which statements are defensible?", "options": ["The code establishes that one vehicle is quantitatively twice another", "A 0/1 indicator cannot affect any Euclidean distance", "Numeric encoding does not itself settle operational importance", "Its relative weight still needs consideration beside other features"]}, {"id": "Q9-18", "topic": "M3", "type": "single", "stem": "One record is stored per hour. Validation takes every 24th record from a fixed starting offset. Which concern is most direct?", "options": ["The split guarantees all daily phases are equally represented", "The evaluation can repeatedly sample the same hour of day", "Each validation record automatically creates 24 folds", "The sampling interval is a learned probability threshold"]}, {"id": "Q9-19", "topic": "M9", "type": "single", "stem": "Two standardized pollution measurements rise and fall together almost identically. Which PCA interpretation is most reasonable?", "options": ["A leading common-movement component may account for most predictor variance", "PCA automatically turns a correlation into independent causal effects", "The first component identifies which source caused pollution", "The smaller component must have the largest eigenvalue"]}, {"id": "Q9-20", "topic": "M8", "type": "multi", "stem": "A model is delay=5+2*distance+7*express, with express coded 1 and local coded 0. Which statements are supported?", "options": ["The local route is the reference for the indicator", "Express buses are proved causally slower by 7", "The express prediction still depends on distance", "At the same distance, the fitted express delay is 7 higher"]}, {"id": "Q9-21", "topic": "M9", "type": "multi", "stem": "A regression uses PCA predictors and a detrended delay response. For a new case, which steps fit that pipeline?", "options": ["Project prepared predictors using the learned loadings", "Add back the fitted future trend for the original-scale prediction", "Predict the remaining response component", "Replace the predicted remainder with the first PCA eigenvalue"]}, {"id": "Q9-22", "topic": "M8", "type": "single", "stem": "Adding a weather term to the same least-squares training fit raises ordinary R-squared slightly but lowers adjusted R-squared. Which interpretation is appropriate?", "options": ["Adjusted R-squared is a class probability", "The fit gain did not offset the adjusted measure's model-size penalty", "The result establishes the weather term has no predictive value anywhere", "The ordinary fit necessarily worsened"]}, {"id": "Q9-23", "topic": "M7", "type": "single", "stem": "A delay model specified as ARIMA(1,2,0) is implemented by regressing raw levels on one previous raw level, without differencing. Which diagnosis is correct?", "options": ["The zero MA count makes every implementation equivalent", "The lag count 1 means differencing is unnecessary", "The implementation omitted the specified two differencing steps", "The middle number selects two raw predictor columns"]}, {"id": "Q9-24", "topic": "M5", "type": "single", "stem": "A transit record has an ordinary distance and ordinary duration individually, but an implausibly short duration for that distance. Which description best fits?", "options": ["Only the row identifier can expose it", "Unusualness can arise from the joint relationship despite ordinary marginal values", "A normal marginal histogram rules out all modeling anomalies", "Every predictor must be individually extreme"]}, {"id": "Q9-25", "topic": "M10", "type": "multi", "stem": "A route-based regression tree predicts expected journey minutes. Dispatch then monitors the ordered residuals for persistent positive change. Which statements distinguish the steps?", "options": ["The tree supplies a case-specific numeric baseline", "An upper CUSUM can monitor upward departures from the defined residual reference", "A positive residual means the observed journey was faster than predicted", "The alarm does not by itself identify a physical cause"]}, {"id": "Q9-26", "topic": "M7", "type": "multi", "stem": "A Holt update uses beta=0 while alpha remains positive. Which statements follow from the stated trend recursion?", "options": ["The level can still update from new observations", "Alpha and beta control different parts of the model", "Beta=0 forces the level to zero", "The trend estimate remains at its previous value"]}, {"id": "Q9-27", "topic": "M6", "type": "single", "stem": "An upper CUSUM has S=10, baseline 20, allowance 1, and new observation 19. Which statement is correct?", "options": ["It becomes 11 because the reading is negative evidence", "It becomes 8, so one below-baseline reading need not reset a large existing statistic", "It alarms only if x exceeds 20 individually", "It resets to zero whenever x<mu"]}, {"id": "Q9-28", "topic": "M3", "type": "multi", "stem": "A dataset is stratified by known late/on-time labels to distribute both groups across sets. Which statements are correct?", "options": ["Using labels to design representative partitions is different from fitting predictive features with all labels", "The held-out labels must still be excluded from model selection and fitting decisions designated for training", "Stratification alone guarantees perfect deployment representativeness", "A response-aware partition can preserve rare outcome coverage"]}, {"id": "Q9-29", "topic": "M2", "type": "single", "stem": "An SVM rule is score=weight-10 and predicts overload when score>0. A report omits the intercept and uses weight>0 instead. What changed?", "options": ["The margin necessarily became optimal", "Only the printed notation changed; every decision is preserved", "The rule became a probability model", "The decision boundary moved from weight 10 to weight 0"]}, {"id": "Q9-30", "topic": "M1", "type": "single", "stem": "A scheduling model produces the minimum delay under assumed travel times and bus availability. Real buses take longer in rain. What is the most useful interpretation?", "options": ["A more complicated method name resolves all missing inputs", "The recommendation is conditional on its representation and assumptions, so reassess relevant weather behavior", "An optimum remains operationally optimal under all changed conditions", "Rain can affect observations but never a mathematical model"]}, {"id": "Q9-31", "topic": "M6", "type": "single", "stem": "A congestion study measures a period from its first change alarm to its last. Which reporting practice is most defensible?", "options": ["Treat the measured duration as proof of one policy effect", "Assume the alarms settle all questions about citywide congestion", "State the operational definitions and settings, and assess how they affect the duration conclusion", "Hide alternative definitions that change the conclusion"]}, {"id": "Q9-32", "topic": "M10", "type": "single", "stem": "With a finite set of higher-is-more-positive scores, a threshold above every score labels all cases negative. Which ROC coordinates result when both true classes are present?", "options": ["(1,1)", "(0,0)", "(.5,.5)", "(0,1)"]}, {"id": "Q9-33", "topic": "M8", "type": "multi", "stem": "An analyst multiplies identical normal error densities to build a regression likelihood. Which assumptions does this simple construction rely on?", "options": ["The assumptions should be examined rather than inferred from the algorithm name", "A common specified normal-error form", "Independence of the modeled errors", "Every response must equal the fitted mean"]}, {"id": "Q9-34", "topic": "M8", "type": "single", "stem": "A delay slope estimate is 2 minutes per kilometer with interval [1,3]. Which statement is most defensible?", "options": ["Each kilometer causes exactly 2 extra minutes under all circumstances", "The interval is the probability of a bus being late", "Every trip must have a delay between 1 and 3 minutes", "Under the model and interval assumptions, the slope has supported positive association with the stated units"]}, {"id": "Q9-35", "topic": "M7", "type": "multi", "stem": "A GARCH variance forecast increases, so a dispatch manager adds reserve capacity. Which statements are appropriate?", "options": ["The capacity decision also depends on consequences and resources", "High variance guarantees a large positive delay tomorrow", "The variance forecast does not by itself choose the exact reserve", "The model provides information about greater predicted variability"]}, {"id": "Q9-36", "topic": "M4", "type": "single", "stem": "A clustering team changes its objective to total absolute one-dimensional distances but retains mean updates solely because that is what k-means does. Which concern is most appropriate?", "options": ["An update justified for squared Euclidean distance is not automatically justified for a changed objective", "All distance objectives have exactly the same minimizing center", "The objective does not matter once k is chosen", "Changing distance creates supervised labels"]}, {"id": "Q9-37", "topic": "M5", "type": "multi", "stem": "A report excludes a strike week from ordinary commute forecasts. The exclusion is relevant to a clearly restricted target. Which statements are appropriate?", "options": ["A justified exclusion needs no documentation", "Do not present the resulting score as all-condition performance", "Analyze the excluded regime separately if the decision also needs strike planning", "Disclose the restriction and excluded operating regime"]}, {"id": "Q9-38", "topic": "M1", "type": "multi", "stem": "A transit agency has unlabeled journey profiles and a separate file of trips labeled accessible or inaccessible. Which statements fit the tasks?", "options": ["The two representations can support different questions", "Classification can use the known accessibility labels", "Unsupervised journey groups are automatically the accessibility classes", "Clustering can explore journey-profile groups"]}, {"id": "Q9-39", "topic": "M1", "type": "multi", "stem": "A transport team wants minutes until the next bus, probability it is late, and an alarm that delays have shifted. Which statements are correct?", "options": ["The word delay forces all three into one model family", "The second is a binary-event probability", "The first output is numeric", "The third is a change-detection output"]}, {"id": "Q9-40", "topic": "M7", "type": "single", "stem": "A multiplicative Holt-Winters update has observation 120, same-phase old seasonal factor 1.2, previous level 90, previous trend 10, and alpha=.5. What is the updated level?", "options": ["120", "100", "110", "60"]}, {"id": "Q9-41", "topic": "M2", "type": "single", "stem": "A new route observation is standardized using training mean 60 and SD 15, giving z=2. Which raw value corresponds?", "options": ["30", "90", "62", "120"]}, {"id": "Q9-42", "topic": "M4", "type": "single", "stem": "An analyst computes WSS by measuring every journey against the largest cluster's center, regardless of membership. What is the correction?", "options": ["Use only the farthest observation in each cluster", "Use each observation's assigned center in the within-cluster sum", "Replace squared distances by class-vote counts", "Use the center with the highest cluster label"]}, {"id": "Q9-43", "topic": "M7", "type": "single", "stem": "A detector records one travel-time response per completed trip, with variable numbers of trips each day. The analyst sets L=24 to represent a daily cycle simply because a day has 24 hours. Which concern applies?", "options": ["All trip series have seasonal period 24", "The observation index is trips, so 24 observations need not be one day", "Calendar duration always equals observation count", "The response automatically becomes hours of the day"]}, {"id": "Q9-44", "topic": "M10", "type": "multi", "stem": "A pruned delay tree has slightly worse training fit but lower representative validation SSE. Which statements are warranted?", "options": ["The result does not establish superiority under every possible operational objective", "The held-out gain supports the pruned candidate for that error objective", "Pruning must always make both training and validation fit worse", "Removing branches can improve generalization"]}, {"id": "Q9-45", "topic": "M4", "type": "multi", "stem": "The geometric centroid of ferry demand lies in open water, but a dock must be on shore. Which statements follow?", "options": ["A k-means center is always one of the observed shore points", "Nearest-center segmentation alone solves the dock-placement constraints", "The operational location decision needs feasibility information", "The mean center can be a useful summary but not a feasible dock"]}, {"id": "Q9-46", "topic": "M4", "type": "blank", "stem": "For coordinate differences (3,4), the infinity-norm distance is ____.", "options": []}, {"id": "Q9-47", "topic": "M5", "type": "tf", "stem": "A large regression residual alone proves a record was incorrectly entered.", "options": []}, {"id": "Q9-48", "topic": "M7", "type": "blank", "stem": "A neutral multiplicative seasonal factor equals ____.", "options": []}, {"id": "Q9-49", "topic": "M8", "type": "blank", "stem": "Residuals 1,-2,3 give sum of squared errors ____.", "options": []}, {"id": "Q9-50", "topic": "M10", "type": "tf", "stem": "A properly formed binary logistic regression probability output lies between zero and one.", "options": []}], [{"id": "Q10-01", "topic": "M6", "type": "multi", "stem": "A refrigeration monitor alarms, and a manager must choose inspection or shutdown. Which statements are warranted?", "options": ["The monitor is distinct from a point forecast of the next temperature", "The action requires consequences and available evidence beyond the statistic alone", "The alarm chooses the only feasible action automatically", "The alarm supports investigating a change"]}, {"id": "Q10-02", "topic": "M6", "type": "single", "stem": "A positive-valued lower CUSUM on refrigerator temperatures alarms. Which interpretation is most direct?", "options": ["Accumulated evidence supports a downward departure from the reference, subject to the stated rules", "A negative temperature must have been measured", "The future temperature is exactly the lower statistic", "The variance is necessarily zero"]}, {"id": "Q10-03", "topic": "M7", "type": "single", "stem": "Two periods have identical newest squared errors but different previous variance estimates in a GARCH update. Which statement is correct?", "options": ["Identical latest errors force identical forecasts in all GARCH specifications", "Variance models never use earlier quantities", "Previous variance can only affect the response mean", "Their variance forecasts can differ because prior variance contributes"]}, {"id": "Q10-04", "topic": "M5", "type": "multi", "stem": "A missing refrigerator temperature is recorded as 999 by the logging system. Which statements are justified?", "options": ["Blindly using it can distort distances and means", "Recognize and handle the missing-value code rather than treating 999 as real temperature", "The numeric code proves an actual catastrophic heat event", "The preparation policy should preserve what is known versus missing"]}, {"id": "Q10-05", "topic": "M7", "type": "multi", "stem": "A sales level drifts, while its first differences look stable. An analyst fits a stationary lag relation to those differences. Which statements are defensible?", "options": ["A stable difference sequence automatically proves a physical cause of growth", "Reconstructing level forecasts requires relating differences back to levels", "Differencing does not make the original levels stop drifting", "Suitability is assessed for the modeled differenced sequence"]}, {"id": "Q10-06", "topic": "M3", "type": "single", "stem": "A frozen spoilage classifier performs poorly on a test population. Which statement is most defensible?", "options": ["Investigate representation, sample differences, and model fit before attributing a single cause", "A poor score proves the model is overfit and nothing else", "The score alone specifies the best replacement family", "A poor score proves labels are all wrong"]}, {"id": "Q10-07", "topic": "M3", "type": "multi", "stem": "One preselected concession model is compared with the best of 100 tuned variants of another family on the same validation set. Which statements are warranted?", "options": ["The winning variant may benefit from favorable validation noise", "Testing many variants guarantees a real improvement", "The number of tried settings can matter to interpreting the headline validation win", "The selected complete procedures need independent final assessment"]}, {"id": "Q10-08", "topic": "M7", "type": "single", "stem": "A seasonal factor 1.3 occurs on weekend food-waste measurements. Which conclusion is supported?", "options": ["The factor indicates better performance because it exceeds one", "Waste is about 30% above the nonseasonal baseline at that phase, not necessarily an improvement", "The waste probability is 130%", "The factor proves staff behavior caused the excess"]}, {"id": "Q10-09", "topic": "M2", "type": "multi", "stem": "A snack-similarity model uses sugar in grams and package weight in grams. An analyst scales only sugar by 100 before Euclidean k-NN. Which conclusions are warranted?", "options": ["All coordinate changes preserve distances because units remain numeric", "A meaningful weighting decision should be distinguished from an accidental rescaling", "The selected neighbors can change", "Sugar differences gain relative influence under the modified distance"]}, {"id": "Q10-10", "topic": "M8", "type": "multi", "stem": "Two equivalent waste regressions use kilograms and grams for the response. Which statements are correct?", "options": ["Response units must be considered when comparing raw error values", "The larger raw SSE proves the gram model predicts worse", "Residuals in grams are 1,000 times their kilogram values", "SSE in grams is 1,000,000 times the kilogram SSE"]}, {"id": "Q10-11", "topic": "M8", "type": "single", "stem": "A regression has intercept, x, x^2, and a 0/1 weekend indicator. Using the lecture coefficient count, how many regression coefficients are fitted?", "options": ["3 because an intercept is never a coefficient", "2 because x and x^2 came from one original variable", "4", "One per observation"]}, {"id": "Q10-12", "topic": "M7", "type": "single", "stem": "Only one seasonal cycle of noisy concession sales is observed. Which response best reflects survey-level caution?", "options": ["The history establishes that seasonality is impossible", "Initialization and estimated patterns may be uncertain; evaluate what the limited history supports", "One cycle guarantees stable seasonal factors forever", "Adding duplicate cycles supplies independent repeated-season evidence"]}, {"id": "Q10-13", "topic": "M9", "type": "multi", "stem": "One unscaled centered component is z=.6*x1+.8*x2. A regression uses yhat=5+10*z. Which statements interpret substitution?", "options": ["The slope of x1 is automatically 10", "One component can produce nonzero slopes for both original predictors", "The implied centered-coordinate slopes are 6 and 8", "If preprocessing had included scaling, raw-unit interpretation would also need reversal"]}, {"id": "Q10-14", "topic": "M4", "type": "single", "stem": "A k-means run has one center with no assigned observations. Which high-level statement is correct?", "options": ["Its ordinary mean update is undefined and needs a stated handling rule", "Its mean is automatically the zero vector in every implementation", "The empty set has a mean equal to its previous WSS", "It becomes the response class with fewest examples"]}, {"id": "Q10-15", "topic": "M7", "type": "multi", "stem": "In Holt-Winters, alpha is held fixed while gamma is increased. Which statements are correct?", "options": ["Other fitted components can still interact through the recursions", "Gamma becomes the number of phases in the cycle", "The seasonal update gives more weight to its newest response-to-level information", "The direct setting of the level-update weight is unchanged"]}, {"id": "Q10-16", "topic": "M4", "type": "single", "stem": "A concession team wants customer taste segments and expected orders per hour from match attributes. Which pairing most directly fits the survey methods?", "options": ["GARCH for taste labels; PCA for guaranteed sales totals", "Poisson regression for unlabeled segments; k-means for a count mean from attributes", "CV for the count probability; CUSUM for fixed taste groups", "k-means for numeric taste-feature groups; Poisson regression for an attribute-dependent count mean"]}, {"id": "Q10-17", "topic": "M3", "type": "multi", "stem": "An analyst chooses an outlier-removal threshold by repeatedly checking validation performance. Which statements are correct?", "options": ["Calling the threshold data cleaning makes validation reuse irrelevant", "The final test should evaluate the resulting policy independently", "The actual deployment use of the policy should be specified", "That threshold has become a selected pipeline setting"]}, {"id": "Q10-18", "topic": "M10", "type": "multi", "stem": "A restaurant wants both expected complaints per shift and probability of at least one complaint as a binary target. Which statements distinguish the survey choices?", "options": ["Binary logistic regression directly targets the specified binary-event probability", "An expected count is automatically the same number as a probability", "Clarify the requested output before selecting the model", "Poisson regression directly targets an attribute-dependent count mean"]}, {"id": "Q10-19", "topic": "M2", "type": "single", "stem": "In unweighted 5-NN, three neighbors vote spoiled and two fresh. A report calls .6 a validated population probability for all similar packages. Which interpretation is strongest?", "options": ["The rule votes spoiled, but the local label fraction alone does not establish probability calibration", "The fraction proves exactly three of the next five packages will spoil", "Voting cannot classify because there is no unanimity", "The class output is fresh because two classes are present"]}, {"id": "Q10-20", "topic": "M3", "type": "single", "stem": "Five-fold CV chooses 7-NN for concessions. A manager keeps only the examples from the best-scoring training fold for deployment. What is the lecture-aligned correction?", "options": ["Keep only that fold because its score identifies universally superior rows", "Use the selected setting with all allowed non-test training data, rather than retaining only a flattering fold", "Average k values from every tried setting to choose the final model", "Merge the held-out test labels into the neighbor list first"]}, {"id": "Q10-21", "topic": "M2", "type": "single", "stem": "A separable classification plot has class-average locations far from the boundary, but a few close examples define narrow margins. Which statement best explains the SVM emphasis?", "options": ["More distant points automatically determine the smallest margin", "The closest margin-constraining examples matter, not just the class averages", "Every class mean must lie on a margin boundary", "The separator is determined solely by averaging every class coordinate"]}, {"id": "Q10-22", "topic": "M6", "type": "single", "stem": "Temperature is changed from Celsius to Fahrenheit using F=32+1.8*C for an upper CUSUM with a matching transformed baseline. To preserve equivalent departures, what should be considered?", "options": ["Convert only the observations while leaving the baseline unchanged", "Keep all tuning numbers unchanged merely because both units measure temperature", "Scale the allowance and threshold by the positive temperature-difference factor", "Add the Fahrenheit offset to every accumulated statistic"]}, {"id": "Q10-23", "topic": "M2", "type": "single", "stem": "A freshness rule predicts acceptable when 2*storage_days+temperature<20. A package moves from (4,8) to (5,7). Which statement is correct?", "options": ["The label changes whenever either predictor changes", "The two coordinates have exactly cancelling effects", "The expression rises from 16 to 17, but both packages remain acceptable under this rule", "The value 17 is the probability of acceptable freshness"]}, {"id": "Q10-24", "topic": "M3", "type": "single", "stem": "A sporting dataset contains many vendor transactions within each match. Deployment predicts demand at entirely new matches. Which evaluation issue matters?", "options": ["A shared event ID is irrelevant when responses are numeric", "A random row split guarantees unseen-event evaluation", "Transactions from the same match should not provide an overly favorable proxy for new-match generalization", "Every transaction is necessarily an independent new match"]}, {"id": "Q10-25", "topic": "M10", "type": "multi", "stem": "A spoilage rule marks only two packages spoiled, both truly spoiled, but misses eight other spoiled packages. Which statements are correct?", "options": ["Perfect precision implies every spoiled package was found", "The two metrics answer different conditional questions", "Sensitivity is .2", "Precision is 1"]}, {"id": "Q10-26", "topic": "M7", "type": "single", "stem": "A sales response is decomposed as baseline 200+10*t plus a modeled remainder. For t=6, the remainder forecast is -15. Which original-scale forecast follows?", "options": ["-15", "245", "275", "260"]}, {"id": "Q10-27", "topic": "M9", "type": "single", "stem": "Two taste components have variances 90 and 10. Purchase preference changes only along the second. Which statement is most appropriate?", "options": ["Keeping only the first maximizes retained predictor variance but can discard the relevant preference signal", "Retaining 90% of predictor variance guarantees 90% classification accuracy", "PCA labels the smaller eigenvalue a false positive", "The first must predict preference better because its variance is larger"]}, {"id": "Q10-28", "topic": "M8", "type": "single", "stem": "A waste regression reports a negative attendance slope after adjusting for menu mix, despite a positive overall attendance-waste correlation. What is the best response?", "options": ["Inspect conditional interpretation and correlated predictors before declaring a contradiction", "The adjusted sign proves increasing attendance reduces waste causally", "A negative fitted sign is impossible whenever marginal correlation is positive", "Remove all adjustment columns solely to match the expected sign"]}, {"id": "Q10-29", "topic": "M10", "type": "single", "stem": "Two spoilage models have similar AUC, but only 20 packages per day can receive extra inspection. Which consideration is most relevant?", "options": ["AUC itself specifies exactly which 20 must be inspected", "Performance and consequences at a feasible inspection policy, beyond overall AUC", "Every threshold generates the same inspection workload", "The model with higher training accuracy necessarily uses less capacity"]}, {"id": "Q10-30", "topic": "M4", "type": "single", "stem": "A cluster center is updated from its current members, and one member becomes closer to a different center afterward. Which statement matches standard k-means?", "options": ["Change its outcome label to force the old membership", "Never move a point after its first assignment", "Reconsider membership in the next assignment step", "Select a random class probability as the new center"]}, {"id": "Q10-31", "topic": "M1", "type": "single", "stem": "A stadium asks for a forecast of concession quality. Which clarification is most necessary before assigning a lecture model?", "options": ["Whether the final file is saved as CSV or text", "Whether the model name contains the word regression", "Whether quality means waiting minutes, a satisfaction category, or another measurable response", "Which algorithm was most recently mentioned in a podcast"]}, {"id": "Q10-32", "topic": "M1", "type": "single", "stem": "Separate demand models predict sales for burgers and salads. The kitchen can prepare only 500 total portions. Which statement is most appropriate?", "options": ["A shared constraint changes every response into a class label", "The preparation choice must consider the shared capacity and consequences in addition to both forecasts", "Higher predictive accuracy automatically removes the capacity constraint", "Each product forecast can independently determine a feasible total allocation"]}, {"id": "Q10-33", "topic": "M8", "type": "single", "stem": "Two comparable candidates have AIC scores 100 and 104. Under relative support exp(-Delta/2), what does the second model receive relative to the best?", "options": ["A guaranteed .135 probability that every coefficient is correct", "exp(-2), about .135, as relative support rather than proof of truth", "exp(2), because higher AIC is preferred", "Zero support because any AIC difference excludes a model"]}, {"id": "Q10-34", "topic": "M2", "type": "multi", "stem": "A sporting classifier uses outcome codes 1=win, 2=draw, 3=loss. Which statements are correct?", "options": ["A classification task can use them as labels", "A mean label of 2.5 is automatically a meaningful outcome category", "The codes represent categories, not necessarily equally spaced quantities", "The coding alone does not define a probability model"]}, {"id": "Q10-35", "topic": "M1", "type": "multi", "stem": "A nutrition team fits a regression to summarize associations between menu attributes and measured waste. Which statements are appropriate?", "options": ["Using regression means only future prediction is permitted", "Coefficient interpretation should consider included predictors and units", "An association summary is not automatically a causal intervention result", "Regression can have a descriptive or inferential use as well as a predictive one"]}, {"id": "Q10-36", "topic": "M5", "type": "multi", "stem": "A vendor is flagged as unusual under a model ignoring stadium section, but ordinary under a section-specific baseline. Which statements are correct?", "options": ["The expected comparison context affects residual unusualness", "The first flag does not establish an invalid record", "The more contextual baseline automatically proves causality", "Both analyses should be interpreted with their modeling assumptions"]}, {"id": "Q10-37", "topic": "M9", "type": "single", "stem": "A food-waste response includes genuine zeros. A team plans the logarithmic member of ordinary positive-response Box-Cox without any further policy. What should be addressed?", "options": ["The log of zero is always one", "PCA of predictors changes zero responses into positive values", "Logarithms of zero are undefined, so the response representation needs an appropriate justified choice", "All genuine zero-waste days must be deleted as errors"]}, {"id": "Q10-38", "topic": "M10", "type": "multi", "stem": "On four cases, a policy has one TP, one FN, one FP, and one TN. Costs are TP=2,FN=10,FP=3,TN=0. Which statements are correct?", "options": ["Average stated cost is 3.75 per case", "Correct decisions can still consume resources", "Ignoring the true-positive cost gives the complete stated total", "Total stated cost is 15"]}, {"id": "Q10-39", "topic": "M6", "type": "single", "stem": "A refrigeration monitor never accumulates evidence for a small sustained shift because each net increment is negative. Which intervention addresses that specific mechanism?", "options": ["Increase the threshold to accumulate faster", "Add more regression coefficients without changing the monitor", "Rename the statistic a probability", "Reconsider the allowance relative to the departure of interest"]}, {"id": "Q10-40", "topic": "M5", "type": "single", "stem": "A storage-duration model excludes all long delays because they are rare, while the application protects spoilage-sensitive food. Which concern is strongest?", "options": ["Exclusion can remove the very tail relevant to safety and loss", "Rare means impossible at deployment", "A normal-looking histogram establishes a safe supply chain", "Removing tails always improves operational decisions"]}, {"id": "Q10-41", "topic": "M4", "type": "multi", "stem": "Two preparation stations have coordinate differences from a target of (4,0) and (3,2). Which statements are correct?", "options": ["Manhattan distance prefers (4,0), since 4<5", "Euclidean distance prefers (3,2), since sqrt(13)<4", "The same nearest site must be chosen by every norm", "The metric should reflect the operational movement rule"]}, {"id": "Q10-42", "topic": "M4", "type": "single", "stem": "A taste clustering produces low WSS, but the groups mix known vegetarian and nonvegetarian customers. Which interpretation is most appropriate?", "options": ["The low WSS proves the dietary labels are wrong", "Increasing cluster names resolves the label mismatch", "Low WSS measures compactness in the selected features, not guaranteed agreement with that external label", "Every unsupervised group must match a supervised category"]}, {"id": "Q10-43", "topic": "M2", "type": "multi", "stem": "A team changes k-NN from three neighbors to seven while keeping feature scaling fixed. Which statements are correct?", "options": ["Changing only k necessarily changes every pairwise feature distance", "It changes the set or number of labels contributing to the vote", "It changes k from a neighborhood size into a cluster count", "It should be evaluated as a changed prediction setting"]}, {"id": "Q10-44", "topic": "M8", "type": "multi", "stem": "A report lists slope estimates, uncertainty intervals, and held-out squared error. Which statements distinguish these summaries?", "options": ["Neither summary alone establishes a causal explanation", "A good held-out score proves every individual slope is stable", "Held-out error addresses prediction performance on evaluated cases", "Intervals address uncertainty in specified fitted relationships"]}, {"id": "Q10-45", "topic": "M10", "type": "single", "stem": "Many trees make the same mistakes because an important pre-decision measurement is absent. Which statement best reflects ensemble limits?", "options": ["More identical trees necessarily supply the missing information", "Averaging cannot manufacture the missing measurement; inspect representation as well as tree diversity", "Every ensemble error is independent by construction", "Omitting a predictor guarantees a simpler tree is always correct"]}, {"id": "Q10-46", "topic": "M3", "type": "tf", "stem": "The average CV score is the exact guaranteed score on the next independent test sample.", "options": []}, {"id": "Q10-47", "topic": "M4", "type": "blank", "stem": "A center uses records 2,2,8. One copy of 2 is verified to be an erroneous duplicate and removed. The recomputed center is ____.", "options": []}, {"id": "Q10-48", "topic": "M7", "type": "blank", "stem": "With previous level 50, new observation 90, and alpha=.1, the updated single-smoothing level is ____.", "options": []}, {"id": "Q10-49", "topic": "M9", "type": "tf", "stem": "Transforming only the predictors changes the response variable into a transformed-response scale automatically.", "options": []}, {"id": "Q10-50", "topic": "M10", "type": "blank", "stem": "A package that is truly spoiled but predicted fresh is a false ____.", "options": []}]];
